function uid(prefix: string) { return `${prefix}-${crypto.randomUUID()}`; }
function inputNumber(value: FormDataEntryValue | null) { return Number(String(value ?? "0").replace(",", ".")) || 0; }
function formatDate(value: string) { return new Intl.DateTimeFormat(activeLocale, { day: "2-digit", month: "short", year: "numeric" }).format(new Date(`${value}T12:00:00`)); }
function operationIdFromPath() { return window.location.pathname.match(/^\/operacoes\/([^/]+)$/)?.[1] ?? null; }
function repairLegacyText(value: string) {
  const replacements: Record<string, string> = { "Or\uFFFDamento": "Orçamento", "or\uFFFDamento": "orçamento", "opera\uFFFD\uFFFDo": "operação", "importa\uFFFD\uFFFDo": "importação", "al\uFFFDquota": "alíquota", "Al\uFFFDquotas": "Alíquotas", "parametriza\uFFFD\uFFFDes": "parametrizações", "Parametriza\uFFFD\uFFFDes": "Parametrizações", "vers\uFFFDo": "versão", "aprova\uFFFD\uFFFDo": "aprovação", "c\uFFFDmbio": "câmbio", "refer\uFFFDncia": "referência", "Descri\uFFFD\uFFFDo": "Descrição", "M\uFFFDtodo": "Método", "N\uFFFDo": "Não", "poss\uFFFDvel": "possível", "par\uFFFDmetros": "parâmetros", "Par\uFFFDmetros": "Parâmetros", "portu\uFFFDrias": "portuárias", "Portu\uFFFDrias": "Portuárias", "Log\uFFFDstica": "Logística", "inclu\uFFFDdo": "incluído", "lan\uFFFDada": "lançada", "A\uFFFD\uFFFDes": "Ações", "altera\uFFFD\uFFFDes": "alterações", "situa\uFFFD\uFFFDdo": "situação", "C\uFFFDmbio": "Câmbio", "Pre\uFFFDo": "Preço", "unit\uFFFDário": "unitário" };
  return Object.entries(replacements).reduce((text, [broken, fixed]) => text.replaceAll(broken, fixed), value);
}
function repairStoredText<T>(value: T): T { if (typeof value === "string") return repairLegacyText(value) as T; if (Array.isArray(value)) return value.map(repairStoredText) as T; if (value && typeof value === "object") return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, repairStoredText(item)])) as T; return value; }
function cnpjRaw(value: string) { return value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 14); }
function cepRaw(value: string) { return value.replace(/\D/g, "").slice(0, 8); }
function formatCep(value: string) { const raw = cepRaw(value); return raw.length > 5 ? `${raw.slice(0, 5)}-${raw.slice(5)}` : raw; }
function formatCnpj(value: string) { const raw = cnpjRaw(value); return [raw.slice(0, 2), raw.slice(2, 5), raw.slice(5, 8), raw.slice(8, 12), raw.slice(12, 14)].filter(Boolean).map((part, index) => index === 0 ? part : index === 3 ? `/${part}` : index === 4 ? `-${part}` : `.${part}`).join(""); }
function cnpjDigit(value: string) { const weights = value.length === 12 ? [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2] : [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]; const remainder = [...value].reduce((sum, character, index) => sum + (character.charCodeAt(0) - 48) * weights[index], 0) % 11; return remainder < 2 ? 0 : 11 - remainder; }
function isValidCnpj(value: string) { const raw = cnpjRaw(value); if (raw.length !== 14 || (/^\d+$/.test(raw) && /^([0-9])\1+$/.test(raw))) return false; const base = raw.slice(0, 12); const first = cnpjDigit(base); return Number(raw[12]) === first && Number(raw[13]) === cnpjDigit(`${base}${first}`); }
function viewFromPath(): View { const path = window.location.pathname; if (path === "/home") return "dashboard"; if (path.startsWith("/operacoes")) return "imports"; if (path === "/clientes") return "customers"; if (path === "/portos") return "ports"; if (path === "/relatorios") return "reports"; if (path === "/usuarios") return "users"; if (path === "/meu-perfil") return "profile"; if (path === "/parametrizacoes") return "settings"; return "dashboard"; }
function viewUrl(view: View) { return ({ dashboard: "/home", imports: "/operacoes", customers: "/clientes", ports: "/portos", reports: "/relatorios", users: "/usuarios", profile: "/meu-perfil", settings: "/parametrizacoes" } as const)[view]; }
