const localizedTextNodes = new WeakMap<Text, LocalizedText>();
const localizableAttributes = ["placeholder", "aria-label", "title", "alt"] as const;
function localizeDocument(locale: Locale) {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const textNodes: Text[] = [];
  let node: Node | null;
  while ((node = walker.nextNode())) textNodes.push(node as Text);
  for (const textNode of textNodes) {
    const parent = textNode.parentElement;
    if (!parent || parent.closest("[data-localized]") || ["SCRIPT", "STYLE", "TEXTAREA"].includes(parent.tagName)) continue;
    const next = localizeLiveText(locale, textNode.nodeValue ?? "", localizedTextNodes.get(textNode));
    localizedTextNodes.set(textNode, next);
    if (textNode.nodeValue !== next.rendered) textNode.nodeValue = next.rendered;
  }
  for (const element of document.querySelectorAll<HTMLElement>("*")) for (const attribute of localizableAttributes) {
    if (element.closest("[data-localized]") || !element.hasAttribute(attribute)) continue;
    const sourceAttribute = `data-i18n-source-${attribute}`;
    const original = element.getAttribute(sourceAttribute) ?? element.getAttribute(attribute) ?? "";
    if (!element.hasAttribute(sourceAttribute)) element.setAttribute(sourceAttribute, original);
    const translated = translateUiText(locale, original);
    if (element.getAttribute(attribute) !== translated) element.setAttribute(attribute, translated);
  }
}
function useUiLocalization(locale: Locale) {
  useEffect(() => {
    for (const attribute of localizableAttributes) document.querySelectorAll(`[data-i18n-source-${attribute}]`).forEach((element) => element.removeAttribute(`data-i18n-source-${attribute}`));
    let queued = false;
    const update = () => { queued = false; localizeDocument(locale); };
    update();
    const observer = new MutationObserver(() => { if (!queued) { queued = true; queueMicrotask(update); } });
    observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: [...localizableAttributes] });
    return () => observer.disconnect();
  }, [locale]);
}

function MarketPulse({ context, error, locale }: { context: MarketContext | null; error: string; locale: Locale }) { if (error) return <div className="market-pulse market-pulse--error" role="status">{t(locale, "operationalDataUnavailable")}</div>; if (!context) return <div className="market-pulse market-pulse--loading" aria-busy="true" aria-label={t(locale, "refreshingOperationalData")}><span className="sr-only">{t(locale, "refreshingOperationalData")}</span><Skeleton className="skeleton--quote" /><Skeleton className="skeleton--headline" /></div>; const quoteTime = new Intl.DateTimeFormat(locale, { dateStyle: "short", timeStyle: "short" }).format(new Date(context.dollar.quotedAt)); return <section className="market-pulse" aria-label={t(locale, "operationalContext")}><div className="market-quote"><Banknote size={16} aria-hidden="true" /><strong className="market-quote__conversion" data-localized title={`BCB PTAX · ${t(locale, "sale")} · ${quoteTime}`}><span>USD 1</span><span className="market-quote__equals">=</span><span>R$ {new Intl.NumberFormat(locale, { minimumFractionDigits: 4, maximumFractionDigits: 4 }).format(context.dollar.sell)}</span><span className="market-quote__equals">=</span><span>CNY {(() => { const yuan = convertCurrency(1, "USD", "CNY", context); return yuan === null ? "—" : new Intl.NumberFormat(locale, { minimumFractionDigits: 4, maximumFractionDigits: 4 }).format(yuan); })()}</span></strong><small>{quoteTime}</small></div>{context.news[0] && <a className="market-news" href={context.news[0].url} target="_blank" rel="noreferrer"><Newspaper size={15} aria-hidden="true" /><span><b>{context.news[0].source}</b>{context.news[0].title}</span></a>}</section>; }

export function App() {
  const [session, setSession] = useState<{ token: string; user: SessionUser } | null>(() => { try { return JSON.parse(sessionStorage.getItem("exporta-brasil-session") || "null") as { token: string; user: SessionUser } | null; } catch { return null; } });
  const [locale, setLocale] = useState<Locale>(() => { const saved = session?.user.preferredLocale ?? localStorage.getItem("exporta-brasil-locale"); return locales.includes(saved as Locale) ? saved as Locale : "pt-BR"; });
  const changeLocale = (next: Locale) => { localStorage.setItem("exporta-brasil-locale", next); setLocale(next); if (!session) return; void apiFetch(`${apiUrl}/api/me`, { method: "PATCH", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ preferredLocale: next }) }).then((response) => response.ok ? response.json() : null).then((user: SessionUser | null) => { if (user) setAuthenticated({ token: session.token, user }); }).catch(() => undefined); };
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  activeLocale = locale;
  useUiLocalization(locale);
  const setAuthenticated = (next: { token: string; user: SessionUser } | null) => { if (next) sessionStorage.setItem("exporta-brasil-session", JSON.stringify(next)); else sessionStorage.removeItem("exporta-brasil-session"); setSession(next); };
  useEffect(() => { const path = window.location.pathname; const destination = !session ? path === "/login" ? null : "/login" : session.user.mustChangePassword ? path === "/primeiro-acesso" ? null : "/primeiro-acesso" : ["/", "/login", "/primeiro-acesso", "/pendencias"].includes(path) ? "/home" : null; if (destination && path !== destination) window.history.replaceState({}, "", destination); }, [session]);
  const logout = () => { window.history.replaceState({}, "", "/login"); setAuthenticated(null); };
  const expireSession = () => { sessionStorage.setItem("exporta-brasil-auth-notice", "Sua sessão expirou. Entre novamente."); logout(); };
  useEffect(() => {
    if (!session) return;
    const unwatch = watchSessionExpiration(session.token, expireSession);
    const validate = () => { void apiFetch(`${apiUrl}/api/me`, { headers: { authorization: `Bearer ${session.token}` } }).catch(() => undefined); };
    const onVisibility = () => { if (document.visibilityState === "visible") validate(); };
    validate();
    document.addEventListener("visibilitychange", onVisibility);
    return () => { unwatch(); document.removeEventListener("visibilitychange", onVisibility); };
  }, [session?.token]);
  if (!session) return <LoginScreen onAuthenticated={setAuthenticated} />;
  if (session.user.mustChangePassword) return <InitialPasswordScreen session={session} onAuthenticated={setAuthenticated} onSessionExpired={expireSession} />;
  return <LocaleContext.Provider value={locale}><BackofficeApp session={session} onSessionUpdate={setAuthenticated} onLogout={logout} locale={locale} onLocaleChange={changeLocale} /></LocaleContext.Provider>;
}

function PasswordInput({ name, placeholder = "Sua senha", autoComplete = "current-password", minLength }: { name: string; placeholder?: string; autoComplete?: string; minLength?: number }) { const [visible, setVisible] = useState(false); return <span className="login-input login-input--password"><LockKeyhole size={18} /><input name={name} type={visible ? "text" : "password"} minLength={minLength} required autoComplete={autoComplete} placeholder={placeholder} /><Toggle className="password-visibility" pressed={visible} onPressedChange={setVisible} aria-label={visible ? "Ocultar senha" : "Mostrar senha"} title={visible ? "Ocultar senha" : "Mostrar senha"}>{visible ? <EyeOff size={17} aria-hidden="true" /> : <Eye size={17} aria-hidden="true" />}</Toggle></span>; }

function AccessLayout({ children }: { children: ReactNode }) { return <main className="login-page"><img src="/port-night-login.png" alt="Operação portuária à noite" style={{ position: "fixed", inset: 0, width: "65.25vw", height: "100vh", display: "block", maxWidth: "none", objectFit: "cover", objectPosition: "right center", transform: "scaleX(-1)", zIndex: 10 }} /><section className="login-scene" aria-hidden="true" /><section className="login-panel">{children}</section></main>; }
function LoginScreen({ onAuthenticated }: { onAuthenticated: (session: { token: string; user: SessionUser }) => void }) { const [error, setError] = useState(() => { const notice = sessionStorage.getItem("exporta-brasil-auth-notice") || ""; sessionStorage.removeItem("exporta-brasil-auth-notice"); return notice; }); const [loading, setLoading] = useState(false); const login = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setLoading(true); setError(""); const form = new FormData(event.currentTarget); try { const response = await apiFetch(`${apiUrl}/api/auth/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: form.get("email"), password: form.get("password") }) }); const payload = await response.json() as { token?: string; user?: SessionUser; message?: string }; if (!response.ok || !payload.token || !payload.user) throw new Error(payload.message || "Não foi possível iniciar a sessão."); onAuthenticated({ token: payload.token, user: payload.user }); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível iniciar a sessão."); } finally { setLoading(false); } }; return <AccessLayout><section className="login-card"><div className="login-brand"><span className="brand-mark" style={{ backgroundImage: `url(${brandMark})` }} role="img" aria-label="Exporta Brasil" /><span><strong>Exporta</strong><small>Brasil</small></span></div><p className="eyebrow">ACESSO OPERACIONAL</p><h1>Boas-vindas.</h1><p>Entre para acompanhar suas operações, custos e decisões portuárias.</p><form autoComplete="on" onSubmit={login}><label><span>E-mail</span><span className="login-input"><Mail size={18} /><input name="email" type="email" required autoComplete="username" placeholder="voce@empresa.com.br" /></span></label><label><span>Senha</span><PasswordInput name="password" /></label>{error && <p className="login-error" role="alert">{error}</p>}<button className="button button--primary login-submit" disabled={loading}>{loading ? "Entrando..." : "Entrar no sistema"}</button></form><small className="login-help">Use as credenciais recebidas do administrador.</small></section></AccessLayout>; }

function InitialPasswordScreen({ session, onAuthenticated, onSessionExpired }: { session: { token: string; user: SessionUser }; onAuthenticated: (next: { token: string; user: SessionUser }) => void; onSessionExpired: () => void }) { const [error, setError] = useState(""); const [loading, setLoading] = useState(false); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const password = String(form.get("password")); if (password !== form.get("confirmation")) return setError("As senhas não coincidem."); setLoading(true); setError(""); try { const response = await apiFetch(`${apiUrl}/api/auth/change-password`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ password }) }); const payload = await response.json() as { user?: SessionUser; message?: string }; if (response.status === 401) return onSessionExpired(); if (!response.ok || !payload.user) return setError(payload.message || "Não foi possível atualizar a senha."); onAuthenticated({ token: session.token, user: payload.user }); } catch { setError("Não foi possível atualizar a senha. Tente novamente."); } finally { setLoading(false); } }; return <AccessLayout><section className="login-card"><p className="eyebrow">PRIMEIRO ACESSO</p><h1>Defina sua senha.</h1><p>Escolha uma senha pessoal para concluir a ativação da sua conta.</p><form autoComplete="on" onSubmit={submit}><label><span>Nova senha</span><PasswordInput name="password" placeholder="Nova senha" autoComplete="new-password" minLength={8} /></label><label><span>Confirme a senha</span><PasswordInput name="confirmation" placeholder="Confirme a senha" autoComplete="new-password" minLength={8} /></label>{error && <p className="login-error" role="alert">{error}</p>}<button className="button button--primary login-submit" disabled={loading}>{loading ? "Concluindo..." : "Concluir acesso"}</button></form></section></AccessLayout>; }

function BackofficeApp({ session, onSessionUpdate, onLogout, locale, onLocaleChange }: { session: { token: string; user: SessionUser }; onSessionUpdate: (next: { token: string; user: SessionUser }) => void; onLogout: () => void; locale: Locale; onLocaleChange: (locale: Locale) => void }) {
  const [view, setView] = useState<View>(viewFromPath);
  const [operations, setOperations] = useState<ImportOperation[]>(() => {
    try { const stored = JSON.parse(localStorage.getItem(storageKey) || "") as Array<Partial<ImportOperation>>; if (!Array.isArray(stored)) throw new Error("Formato inválido"); return repairStoredText(stored).map((operation) => ({ ...operation, items: Array.isArray(operation.items) ? operation.items : [], timeline: Array.isArray(operation.timeline) ? operation.timeline : [], tasks: Array.isArray(operation.tasks) ? operation.tasks : [], documents: Array.isArray(operation.documents) ? operation.documents : [], status: operation.status && operation.status in importStatusMeta ? operation.status : "draft", portStatus: operation.portStatus && operation.portStatus in portStatusMeta ? operation.portStatus : "awaiting_departure", eta: operation.eta || new Date().toISOString().slice(0, 10), customsChannel: (operation.customsChannel as string | undefined) === "pending" ? "unassigned" : operation.customsChannel && operation.customsChannel in customsChannelMeta ? operation.customsChannel : "unassigned" } as ImportOperation)); } catch { return initialOperations; }
  });
  const [customers, setCustomers] = useState<Customer[]>(() => {
    try { return JSON.parse(localStorage.getItem(customersStorageKey) || "") as Customer[]; } catch { return initialCustomers; }
  });
  const [selectedId, setSelectedId] = useState("imp-001");
  const [detailId, setDetailId] = useState<string | null>(operationIdFromPath);
  const [operationsUrlState, setOperationsUrlState] = useState(() => window.location.search);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showNewImport, setShowNewImport] = useState(false);
  const [creatingImport, setCreatingImport] = useState(false);
  const creatingImportRef = useRef(false);
  const [createImportError, setCreateImportError] = useState("");
  const [showNewItem, setShowNewItem] = useState(false);
  const [showProductSheetImport, setShowProductSheetImport] = useState(false);
  const [editingItem, setEditingItem] = useState<ImportItem | null>(null);
  const [itemToRemove, setItemToRemove] = useState<ImportItem | null>(null);
  const [showTimelineEntry, setShowTimelineEntry] = useState(false);
  const [showOperationTask, setShowOperationTask] = useState(false);
  const [editingTask, setEditingTask] = useState<OperationTask | null>(null);
  const [taskToRemove, setTaskToRemove] = useState<OperationTask | null>(null);
  const [showOperationDocument, setShowOperationDocument] = useState(false);
  const [showNewCustomer, setShowNewCustomer] = useState(false);
  const [showCustomerPicker, setShowCustomerPicker] = useState(false);
  const [showPortPicker, setShowPortPicker] = useState(false);
  const [importPort, setImportPort] = useState("");
  const [portOperationId, setPortOperationId] = useState<string | null>(null);
  const [showImportCustomerForm, setShowImportCustomerForm] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [importCustomerId, setImportCustomerId] = useState("");
  const [portFacilities, setPortFacilities] = useState<PortFacility[]>([]);
  const [portCatalogState, setPortCatalogState] = useState<"idle" | "loading" | "ready" | "error">("idle");
  const [portCatalogError, setPortCatalogError] = useState("");
  const [marketContext, setMarketContext] = useState<MarketContext | null>(null);
  const [marketContextError, setMarketContextError] = useState("");
  const [teamMembers, setTeamMembers] = useState<SessionUser[]>([session.user]);
  const [teamMembersLoading, setTeamMembersLoading] = useState(true);
  const operationSync = useOperationSync(apiUrl, session.token, operations, setOperations);
  useEffect(() => {
    if (!operationSync.ready || !detailId) return;
    const section = window.location.hash.slice(1);
    if (["tasks", "documents", "timeline"].includes(section)) document.getElementById(section)?.scrollIntoView({ block: "start" });
  }, [operationSync.ready, detailId]);

  useEffect(() => { localStorage.setItem(storageKey, JSON.stringify(operations)); }, [operations]);
  useEffect(() => { localStorage.setItem(customersStorageKey, JSON.stringify(customers)); }, [customers]);
  useEffect(() => { const syncRoute = () => { setView(viewFromPath()); setDetailId(operationIdFromPath()); setOperationsUrlState(window.location.search); }; window.addEventListener("popstate", syncRoute); return () => window.removeEventListener("popstate", syncRoute); }, []);
  useEffect(() => {
    let active = true;
    const load = () => apiFetch(`${apiUrl}/api/market-context`).then(async (response) => { if (!response.ok) throw new Error((await response.json() as { message?: string }).message); return response.json() as Promise<MarketContext>; }).then((data) => { if (active) { setMarketContext(data); setMarketContextError(""); } }).catch((error: unknown) => { if (active) setMarketContextError(error instanceof Error ? error.message : "Não foi possível atualizar os dados operacionais."); });
    load(); const timer = window.setInterval(load, 15 * 60 * 1000); return () => { active = false; window.clearInterval(timer); };
  }, []);
  const loadPortCatalog = () => {
    setPortCatalogState("loading"); setPortCatalogError("");
    apiFetch(`${apiUrl}/api/port-facilities`).then(async (response) => {
      if (!response.ok) throw new Error((await response.json() as { message?: string }).message ?? "Não foi possível carregar o catálogo.");
      return response.json() as Promise<{ data: PortFacility[] }>;
    }).then((payload) => { setPortFacilities(payload.data); setPortCatalogState("ready"); }).catch((error: unknown) => {
      setPortCatalogError(error instanceof Error ? error.message : "Não foi possível carregar o catálogo."); setPortCatalogState("error");
    });
  };
  useEffect(() => { let active = true; apiFetch(`${apiUrl}/api/users`, { headers: { authorization: `Bearer ${session.token}` } }).then((response) => response.ok ? response.json() : []).then((data: SessionUser[]) => { if (active && Array.isArray(data) && data.length) setTeamMembers(data); }).catch(() => undefined).finally(() => { if (active) setTeamMembersLoading(false); }); return () => { active = false; }; }, [session.token]);
  useEffect(() => { if (view === "ports" && portCatalogState === "idle") loadPortCatalog(); }, [view, portCatalogState]);
  useEffect(() => { if (showNewImport && portCatalogState === "idle") loadPortCatalog(); }, [showNewImport, portCatalogState]);
  const selected = operations.find((operation) => operation.id === (detailId ?? selectedId)) ?? operations.find((operation) => operation.id === selectedId) ?? operations[0];
  const totalInProgress = operations.filter((item) => !["completed", "cleared"].includes(effectiveOperationStatus(item))).length;
  const totalValue = useMemo(() => operations.reduce((sum, operation) => sum + calculateImport(operation).totalCost, 0), [operations]);
  const lookupCompany = async (taxId: string) => {
    const response = await apiFetch(`${apiUrl}/api/companies/${encodeURIComponent(cnpjRaw(taxId))}`);
    const payload = await response.json() as CompanyLookup | { message?: string };
    if (!response.ok || !("legalName" in payload)) throw new Error("message" in payload ? payload.message || "Não foi possível consultar o CNPJ." : "Não foi possível consultar o CNPJ.");
    return payload;
  };
  const lookupAddress = async (postalCode: string) => {
    const response = await apiFetch(`${apiUrl}/api/addresses/${encodeURIComponent(cepRaw(postalCode))}`);
    const payload = await response.json() as AddressLookup | { message?: string };
    if (!response.ok || !("street" in payload)) throw new Error("message" in payload ? payload.message || "Não foi possível consultar o CEP." : "Não foi possível consultar o CEP.");
    return payload;
  };

  type OperationAudit = Pick<OperationTimelineEntry, "title" | "description" | "type">;
  const updateOperation = (id: string, changes: Partial<ImportOperation>, audit?: OperationAudit) => {
    setOperations((current) => current.map((operation) => {
      if (operation.id !== id) return operation;
      if (changes.status && !operationStatusOptions({ ...operation, ...changes }).includes(changes.status)) return operation;
      if (changes.container !== undefined && !hasApprovedBudget(operation)) return operation;
      let automaticAudit: OperationAudit | undefined;
      if (changes.assigneeId !== undefined && changes.assigneeId !== operation.assigneeId) automaticAudit = changes.assigneeName ? { title: "Responsável atribuído", description: `${changes.assigneeName} passou a acompanhar esta importação.`, type: "milestone" } : { title: "Responsável removido", description: "A importação ficou sem responsável definido.", type: "milestone" };
      else if (changes.status && changes.status !== operation.status) automaticAudit = { title: "Status da operação atualizado", description: `${importStatusMeta[operation.status].label} → ${importStatusMeta[changes.status].label}.`, type: "milestone" };
      else if (changes.portStatus && changes.portStatus !== operation.portStatus) automaticAudit = { title: "Status portuário atualizado", description: `${portStatusMeta[operation.portStatus].label} → ${portStatusMeta[changes.portStatus].label}.`, type: "milestone" };
      else if (changes.customsChannel && changes.customsChannel !== operation.customsChannel) automaticAudit = { title: "Canal aduaneiro atualizado", description: `${customsChannelMeta[operation.customsChannel].label} → ${customsChannelMeta[changes.customsChannel].label}.`, type: "milestone" };
      else if (changes.port !== undefined && changes.port !== operation.port) automaticAudit = { title: "Porto de destino atualizado", description: `${operation.port || "Porto a definir"} → ${changes.port || "Porto a definir"}.`, type: "milestone" };
      else if (changes.container !== undefined && changes.container !== operation.container) automaticAudit = { title: "Contêiner atualizado", description: `${operation.container || "Não informado"} → ${changes.container || "Não informado"}.`, type: "milestone" };
      const record = audit ?? automaticAudit;
      const recordedAt = new Date().toISOString();
      const timeline = record ? [...operationTimeline(operation), { id: uid("timeline"), ...record, occurredAt: recordedAt, actorId: session.user.id, actorName: session.user.name, recordedAt }] : changes.timeline;
      return { ...operation, ...changes, ...(timeline ? { timeline } : {}), updatedAt: recordedAt };
    }));
  };

  const createOperation = async (event: FormEvent<HTMLFormElement>, importedItems: ImportedProduct[] = [], sheetBudget?: SheetBudget) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (creatingImportRef.current) return;
    const customerId = String(form.get("customerId"));
    const customer = customers.find((item) => item.id === customerId);
    if (!customer) { setCreateImportError("Selecione um cliente."); return; }
    creatingImportRef.current = true; setCreatingImport(true); setCreateImportError("");
    try {
      const response = await apiFetch(`${apiUrl}/api/imports`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ customerId, customer: customer.tradeName || customer.legalName, port: String(form.get("port") || ""), eta: String(form.get("eta")), existingReferences: operations.map((operation) => operation.reference) }) });
      const payload = await response.json() as { id?: string; reference?: string; message?: string };
      if (!response.ok || !payload.id || !payload.reference) throw new Error(payload.message || "Não foi possível criar a importação. Tente novamente.");
    const operation: ImportOperation = {
      id: payload.id, reference: payload.reference,
      customerId, customer: customer.tradeName || customer.legalName, assigneeId: session.user.id, assigneeName: session.user.name, port: String(form.get("port")),
      container: "", eta: String(form.get("eta")), status: "draft", portStatus: "awaiting_departure", customsChannel: "unassigned",
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), exchangeRate: 5.4, freightBrl: 0, insuranceBrl: 0, portExpensesBrl: 0, shipmentStatus: "not_shipped", budgets: [{ ...newBudget(5.4), ...sheetBudget }], actualExpenses: [], items: importedItems.map((item) => ({ ...item, id: uid("item") })),
      timeline: [{ id: uid("timeline"), title: "Operação criada", description: importedItems.length ? `Processo aberto com ${importedItems.length} produto(s) importados por planilha.` : "Processo aberto para acompanhamento operacional.", occurredAt: new Date().toISOString(), actorId: session.user.id, actorName: session.user.name, recordedAt: new Date().toISOString(), type: "milestone" }]
    };
    setOperations((current) => [operation, ...current]); setImportCustomerId(""); setShowNewImport(false); setImportPort(""); openOperation(operation.id);
    } catch (error) { setCreateImportError(error instanceof Error ? error.message : "Não foi possível criar a importação. Tente novamente."); }
    finally { creatingImportRef.current = false; setCreatingImport(false); }
  };

  const saveCustomer = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const details = { legalName: String(form.get("legalName")), tradeName: String(form.get("tradeName")) || String(form.get("legalName")), taxId: formatCnpj(String(form.get("taxId"))), contactName: String(form.get("contactName")), email: String(form.get("email")), phone: String(form.get("phone")), postalCode: String(form.get("postalCode")), street: String(form.get("street")), number: String(form.get("number")), complement: String(form.get("complement")), district: String(form.get("district")), city: String(form.get("city")), state: String(form.get("state")).toUpperCase(), registrationStatus: String(form.get("registrationStatus")) };
    if (editingCustomer) {
      setCustomers((current) => current.map((customer) => customer.id === editingCustomer.id ? { ...customer, ...details } : customer));
    } else {
      const customer: Customer = { id: uid("customer"), ...details, status: "active", createdAt: new Date().toISOString() };
      setCustomers((current) => [customer, ...current]); setImportCustomerId(customer.id);
    }
    setEditingCustomer(null); setShowNewCustomer(false);
  };

  const saveImportCustomer = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const legalName = String(form.get("legalName"));
    const customer: Customer = { id: uid("customer"), legalName, tradeName: String(form.get("tradeName")) || legalName, taxId: formatCnpj(String(form.get("taxId"))), contactName: String(form.get("contactName")), email: String(form.get("email")), phone: String(form.get("phone")), postalCode: String(form.get("postalCode")), street: String(form.get("street")), number: String(form.get("number")), complement: String(form.get("complement")), district: String(form.get("district")), city: String(form.get("city")), state: String(form.get("state")).toUpperCase(), registrationStatus: String(form.get("registrationStatus")), status: "active", createdAt: new Date().toISOString() };
    setCustomers((current) => [customer, ...current]); setImportCustomerId(customer.id); setShowImportCustomerForm(false); setShowCustomerPicker(false);
  };

  const saveItem = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const optionalText = (name: string) => String(form.get(name) || "").trim() || undefined;
    const optionalNumber = (name: string) => { const value = inputNumber(form.get(name)); return value || undefined; };
    const item: ImportItem = {
      ...editingItem,
      id: editingItem?.id ?? uid("item"), name: String(form.get("name")), ncm: String(form.get("ncm")), quantity: inputNumber(form.get("quantity")),
      unitPriceUsd: inputNumber(form.get("unitPriceUsd")), netWeightKg: optionalNumber("netWeightKg"), grossWeightKg: inputNumber(form.get("grossWeightKg")), iiRate: 0, ipiRate: 0, taxRates: (Object.keys(taxRateLabels) as TaxRateCode[]).filter((code) => form.has(`tax_${code}`)).map((code) => { const rate = inputNumber(form.get(`tax_${code}`)); const existing = editingItem?.taxRates?.find(entry => entry.code === code); return existing && existing.rate === rate ? existing : { code, rate, source: "manual" as const, overridden: true, updatedAt: new Date().toISOString() }; }),
      chineseName: editingItem?.chineseName ?? optionalText("chineseName"), englishName: optionalText("englishName"), sku: optionalText("sku"), description: optionalText("description"), leadTime: editingItem?.leadTime,
      boxWeightKg: optionalNumber("boxWeightKg"), boxCount: optionalNumber("boxCount"), unitsPerBox: optionalNumber("unitsPerBox"), totalVolumeM3: optionalNumber("totalVolumeM3"), lengthCm: editingItem?.lengthCm, widthCm: editingItem?.widthCm, heightCm: editingItem?.heightCm
    };
    updateOperation(selected.id, { items: editingItem ? selected.items.map((current) => current.id === item.id ? item : current) : [...selected.items, item] }, { title: editingItem ? "Produto atualizado" : "Produto adicionado", description: `${item.name} foi ${editingItem ? "atualizado" : "incluído"} na importação.`, type: "milestone" });
    setEditingItem(null); setShowNewItem(false);
  };
  const importProducts = (items: ImportedProduct[], sheetBudget?: SheetBudget) => { if (!selected || !items.length) return; const addedItems = items.map((item) => ({ ...item, id: uid("item") })); updateOperation(selected.id, { items: [...selected.items, ...addedItems], ...(sheetBudget && !hasApprovedBudget(selected) && selected.items.length === 0 ? { budgets: [...(selected.budgets ?? []).map(budget => ({ ...budget, status: budget.status === "draft" ? "superseded" as const : budget.status })), { ...newBudget(sheetBudget.exchangeRate), ...sheetBudget, number: Math.max(0, ...(selected.budgets ?? []).map(budget => budget.number)) + 1 }] } : {}) }, { title: "Produtos importados", description: `${addedItems.length} produto(s) foram incluídos por planilha.`, type: "milestone" }); setShowProductSheetImport(false); };
  const removeItem = () => { if (!selected || !itemToRemove) return; updateOperation(selected.id, { items: selected.items.filter((item) => item.id !== itemToRemove.id) }, { title: "Produto removido", description: `${itemToRemove.name} foi removido da importação.`, type: "milestone" }); setItemToRemove(null); };
  const addTimelineEntry = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const entry: OperationTimelineEntry = { id: uid("timeline"), title: String(form.get("title")), description: String(form.get("description")) || undefined, occurredAt: String(form.get("occurredAt")) || new Date().toISOString(), actorId: session.user.id, actorName: session.user.name, recordedAt: new Date().toISOString(), type: String(form.get("type")) as OperationTimelineEntry["type"] };
    updateOperation(selected.id, { timeline: [...operationTimeline(selected), entry] }); setShowTimelineEntry(false);
  };
  const addOperationTask = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const responsible = teamMembers.find((user) => user.id === form.get("assigneeId"));
    const task: OperationTask = { ...(editingTask ?? { id: uid("task"), completed: false, createdAt: new Date().toISOString() }), title: String(form.get("title")).trim(), assigneeId: responsible?.id, assignee: responsible?.name ?? (form.get("assigneeId") === "legacy" ? editingTask?.assignee : undefined), dueDate: String(form.get("dueDate")) || undefined };
    updateOperation(selected.id, { tasks: editingTask ? operationTasks(selected).map((current) => current.id === task.id ? task : current) : [...operationTasks(selected), task] }, { title: editingTask ? "Pendência atualizada" : "Pendência criada", description: `${task.title}${task.assignee ? ` — responsável: ${task.assignee}` : ""}.`, type: "milestone" }); setShowOperationTask(false); setEditingTask(null);
  };
  const removeOperationTask = () => {
    if (!selected || !taskToRemove) return;
    updateOperation(selected.id, { tasks: operationTasks(selected).filter((task) => task.id !== taskToRemove.id) }, { title: "Pendência excluída", description: taskToRemove.title, type: "milestone" });
    setTaskToRemove(null);
  };
  const addOperationDocument = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selected) return;
    const form = new FormData(event.currentTarget);
    const document: OperationDocument = { id: uid("document"), type: String(form.get("type")), title: String(form.get("title")), reference: String(form.get("reference")) || undefined, issuedAt: String(form.get("issuedAt")) || undefined, expiresAt: String(form.get("expiresAt")) || undefined, status: String(form.get("status")) as OperationDocument["status"], createdAt: new Date().toISOString() };
    updateOperation(selected.id, { documents: [...(selected.documents ?? []), document] }, { title: "Documento registrado", description: `${document.title} foi registrado na operação.`, type: "milestone" }); setShowOperationDocument(false);
  };
  const completeOperationTask = (taskId: string) => { if (!selected) return; const task = operationTasks(selected).find((item) => item.id === taskId); if (!task) return; updateOperation(selected.id, { tasks: operationTasks(selected).map((item) => item.id === taskId ? { ...item, completed: !item.completed } : item) }, { title: task.completed ? "Pendência reaberta" : "Pendência concluída", description: task.title, type: "milestone" }); };

  const changeView = (next: View) => { window.history.pushState({}, "", viewUrl(next)); setView(next); setDetailId(null); setOperationsUrlState(window.location.search); setSidebarOpen(false); };
  const openOperations = (filters: Partial<OperationsFilters> = {}) => { const next = { ...operationsFiltersFromUrl(), ...filters }; const url = operationsUrl(next); window.history.pushState({}, "", url); setOperationsUrlState(window.location.search); setDetailId(null); setView("imports"); };
  const updateOperationsFilters = (filters: OperationsFilters) => { window.history.pushState({}, "", operationsUrl(filters)); setOperationsUrlState(window.location.search); };
  const openOperation = (id: string) => { window.history.pushState({}, "", `/operacoes/${id}${window.location.search}`); setSelectedId(id); setDetailId(id); setView("imports"); };
  const closeOperationDetail = () => { window.history.pushState({}, "", `/operacoes${window.location.search}`); setDetailId(null); };
  const openNotificationOperation = (id: string, section: string) => {
    const target = ["tasks", "documents", "timeline"].includes(section) ? section : "timeline";
    window.history.pushState({}, "", `/operacoes/${encodeURIComponent(id)}#${target}`);
    setSelectedId(id); setDetailId(id); setView("imports"); setOperationsUrlState("");
    window.setTimeout(() => document.getElementById(target)?.scrollIntoView({ behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth", block: "start" }), 100);
  };
  return <CurrencyContext.Provider value={{ rates: marketContext, loading: !marketContext && !marketContextError }}><div className="app-shell">
    {!operationSync.ready && <div className="operation-sync-gate" role="status" data-localized><div><h2>{translateUiText(locale, "Operações")}</h2>{operationSync.error ? <><p>{operationSync.error}</p><Button className="button button--primary" onClick={operationSync.retry}>{translateUiText(locale, "Tentar novamente")}</Button></> : <><Spinner /><div className="notification-skeleton"><span /><span /><span /></div></>}</div></div>}
    <aside className={`sidebar ${sidebarOpen ? "sidebar--open" : ""}`} aria-label="Navegação principal">
      <div className="brand"><span className="brand-mark" style={{ backgroundImage: `url(${brandMark})` }} role="img" aria-label="Exporta Brasil" /><span><strong>Exporta</strong><small>Brasil</small></span><button className="icon-button mobile-only" onClick={() => setSidebarOpen(false)} aria-label="Fechar menu"><X size={20} /></button></div>
      <nav>{navigation.filter((item) => item.id !== "users" || session.user.role === "admin").map(({ id, labelKey, icon: Icon }) => <button key={id} className={`nav-item ${view === id ? "is-active" : ""}`} onClick={() => changeView(id)}><Icon size={19} /><span>{t(locale, labelKey)}</span></button>)}</nav>
      <div className="sidebar-footer"><div className="user-card"><button className="user-profile-trigger" onClick={() => changeView("profile")}><UserAvatar user={session.user} /><span><strong>{session.user.name}</strong><small>{session.user.jobTitle || (session.user.role === "admin" ? "Administrador" : "Operador")}</small></span></button><button className="logout-button" onClick={onLogout}>{t(locale, "signOut")}</button></div></div>
    </aside>
    {sidebarOpen && <button className="scrim" onClick={() => setSidebarOpen(false)} aria-label="Fechar menu" />}
    <main className="main-content" inert={!operationSync.ready}>
      {operationSync.error && <div className="operation-sync-error" role="alert" data-localized><span>{operationSync.error}</span><Button onClick={operationSync.retry}>{translateUiText(locale, "Tentar novamente")}</Button></div>}{operationSync.saving && <div className="operation-sync-saving" role="status" data-localized><Spinner />{locale === "en-US" ? "Saving…" : locale === "zh-CN" ? "正在保存…" : "Salvando…"}</div>}<header className="topbar"><button className="icon-button mobile-only" onClick={() => setSidebarOpen(true)} aria-label="Abrir menu"><Menu size={21} /></button><nav className="breadcrumb" aria-label="Caminho de navegação">{view === "dashboard" ? <strong>{t(locale, "home")}</strong> : <><button onClick={() => changeView("dashboard")}>{t(locale, "home")}</button><ChevronRight size={15} />{detailId && view === "imports" ? <><button onClick={closeOperationDetail}>{t(locale, "operations")}</button><ChevronRight size={15} /><strong>{selected?.reference}</strong></> : <strong>{view === "profile" ? t(locale, "profile") : (() => { const item = navigation.find((entry) => entry.id === view); return item ? t(locale, item.labelKey) : ""; })()}</strong>}</>}</nav><MarketPulse context={marketContext} error={marketContextError} locale={locale} /><div className="top-actions"><LanguageSelect locale={locale} onChange={onLocaleChange} /><button className="icon-button" aria-label={t(locale, "search")}><Search size={19} /></button><Notifications apiUrl={apiUrl} token={session.token} onOpen={openNotificationOperation} /><button className="icon-button" aria-label={t(locale, "help")}><CircleHelp size={19} /></button></div></header>
      {view === "dashboard" && <Dashboard operations={operations} totalInProgress={totalInProgress} totalValue={totalValue} marketContext={marketContext} marketContextError={marketContextError} locale={locale} onOpen={() => openOperations()} onOpenChannel={(channel) => openOperations({ channel, page: 1 })} userId={session.user.id} onOpenOperation={openOperation} onOpenTask={(id) => openNotificationOperation(id, "tasks")} />}
       {view === "imports" && !detailId && <OperationsListView operations={operations} urlState={operationsUrlState} onFiltersChange={updateOperationsFilters} onNew={() => setShowNewImport(true)} onOpen={openOperation} />}
       {view === "imports" && detailId && selected && <OperationDetailPage selected={selected} onBack={closeOperationDetail} onAddItem={() => { setEditingItem(null); setShowNewItem(true); }} onImportProducts={() => setShowProductSheetImport(true)} onEditItem={(item) => { setEditingItem(item); setShowNewItem(true); }} onRemoveItem={setItemToRemove} onAddTimeline={() => setShowTimelineEntry(true)} onAddTask={() => { setEditingTask(null); setShowOperationTask(true); }} onEditTask={(task) => { setEditingTask(task); setShowOperationTask(true); }} onRemoveTask={setTaskToRemove} onApproveCosts={() => { if (!selected || hasApprovedBudget(selected) || !calculateImport(selected).calculationReady) return; updateOperation(selected.id, approveOperationCosts(selected, operationBudget(selected), session.user.name), { title: "Custos aprovados", description: "Os custos foram aprovados. A operação está pronta para acompanhar o embarque.", type: "milestone" }); }} onAddDocument={() => setShowOperationDocument(true)} onToggleTask={completeOperationTask} onEditPort={() => { setPortOperationId(selected.id); if (portCatalogState === "idle") loadPortCatalog(); }} onUpdate={updateOperation} users={teamMembers} usersLoading={teamMembersLoading} />}
       {view === "ports" && <PortsCatalogView facilities={portFacilities} state={portCatalogState} error={portCatalogError} onRetry={loadPortCatalog} />}
       {view === "customers" && <CustomersView customers={customers} operations={operations} onNew={() => { setEditingCustomer(null); setShowNewCustomer(true); }} onEdit={(customer) => { setEditingCustomer(customer); setShowNewCustomer(true); }} />}
       {view === "users" && session.user.role === "admin" && <UsersManagementView token={session.token} onSessionExpired={onLogout} onUserUpdated={(user) => { setTeamMembers((current) => current.some((item) => item.id === user.id) ? current.map((item) => item.id === user.id ? user : item) : [...current, user]); if (user.id === session.user.id) { if (user.role !== "admin") changeView("profile"); onSessionUpdate({ token: session.token, user }); } }} />}
       {view === "profile" && <MyProfileView session={session} onSessionUpdate={onSessionUpdate} />}
       {view === "reports" && <ReportsView operations={operations} customers={customers} marketContext={marketContext} onOpenOperation={openOperation} onOpenOperations={() => openOperations()} />}
       {view === "settings" && <TaxSettingsView token={session.token} />}
    </main>
    <nav className="bottom-nav" aria-label="Navegação móvel">{navigation.slice(0, 4).map(({ id, labelKey, icon: Icon }) => <button key={id} className={view === id ? "is-active" : ""} onClick={() => changeView(id)}><Icon size={19} /><span>{t(locale, labelKey)}</span></button>)}</nav>
    {portOperationId && <Dialog title="Selecionar porto" className="dialog--wide" onClose={() => setPortOperationId(null)}><PortPickerContent facilities={portFacilities} state={portCatalogState} error={portCatalogError} onRetry={loadPortCatalog} onBack={() => setPortOperationId(null)} onSelect={(port) => { updateOperation(portOperationId, { port }); setPortOperationId(null); }} /></Dialog>}
    {showNewImport && <Dialog title={showImportCustomerForm ? "Novo cliente" : showCustomerPicker ? "Selecionar cliente" : showPortPicker ? "Selecionar porto" : "Nova importação"} className="dialog--wide" onClose={() => { setShowNewImport(false); setCreateImportError(""); setImportPort(""); setShowPortPicker(false); setShowCustomerPicker(false); setShowImportCustomerForm(false); setImportCustomerId(""); }}><div hidden={showCustomerPicker || showImportCustomerForm || showPortPicker}><ImportForm token={session.token} creating={creatingImport} error={createImportError} customers={customers} customerId={importCustomerId} port={importPort} onSelectPort={() => setShowPortPicker(true)} onSelectCustomer={() => setShowCustomerPicker(true)} onNewCustomer={() => setShowImportCustomerForm(true)} onSubmit={createOperation} /></div>{showPortPicker && <PortPickerContent facilities={portFacilities} state={portCatalogState} error={portCatalogError} onRetry={loadPortCatalog} onBack={() => setShowPortPicker(false)} onSelect={(port) => { setImportPort(port); setShowPortPicker(false); }} />}{showCustomerPicker && <CustomerPickerContent customers={customers} onBack={() => setShowCustomerPicker(false)} onNewCustomer={() => { setShowCustomerPicker(false); setShowImportCustomerForm(true); }} onSelect={(id) => { setImportCustomerId(id); setShowCustomerPicker(false); }} />}{showImportCustomerForm && <CustomerForm customer={null} onSubmit={saveImportCustomer} onLookup={lookupCompany} onAddressLookup={lookupAddress} onCancel={() => setShowImportCustomerForm(false)} />}</Dialog>}
    {showNewItem && <Dialog title={editingItem ? "Editar produto" : "Adicionar produto"} onClose={() => { setEditingItem(null); setShowNewItem(false); }}><ItemForm budget={selected ? calculateImport(selected).budget : undefined} item={editingItem} onSubmit={saveItem} token={session.token} /></Dialog>}
    {showProductSheetImport && <Dialog title="Importar produtos por planilha" className="dialog--wide" onClose={() => setShowProductSheetImport(false)}><ProductSheetImportDialogContent token={session.token} allowBudget={Boolean(selected && !selected.items.length && !hasApprovedBudget(selected))} onConfirm={importProducts} /></Dialog>}
    {itemToRemove && <Dialog title="Remover produto" onClose={() => setItemToRemove(null)}><div className="confirmation-dialog"><p>Remover <strong>{itemToRemove.name || itemToRemove.chineseName}</strong> desta importação? Os cálculos de rateio e custo total serão atualizados.</p><div><button className="button button--secondary" type="button" onClick={() => setItemToRemove(null)}>Cancelar</button><button className="button button--danger" type="button" onClick={removeItem}><Trash2 size={17} /> Remover produto</button></div></div></Dialog>}
    {showTimelineEntry && <Dialog title="Registrar marco" onClose={() => setShowTimelineEntry(false)}><TimelineEntryForm onSubmit={addTimelineEntry} /></Dialog>}
    {showOperationTask && <Dialog title={editingTask ? "Editar pendência" : "Nova pendência"} onClose={() => { setShowOperationTask(false); setEditingTask(null); }}><OperationTaskForm key={editingTask?.id ?? "new"} task={editingTask} onSubmit={addOperationTask} users={teamMembers} usersLoading={teamMembersLoading} /></Dialog>}
    {taskToRemove && <Dialog title="Excluir pendência" onClose={() => setTaskToRemove(null)}><div className="confirmation-dialog" data-localized><p>{translateUiText(activeLocale, "Deseja excluir esta pendência?")} <strong>{taskToRemove.title}</strong></p><div><Button className="button button--secondary" onClick={() => setTaskToRemove(null)}>{translateUiText(activeLocale, "Cancelar")}</Button><Button className="button button--danger" onClick={removeOperationTask}><Trash2 size={17} /> {translateUiText(activeLocale, "Excluir pendência")}</Button></div></div></Dialog>}
    {showOperationDocument && <Dialog title="Registrar documento" onClose={() => setShowOperationDocument(false)}><OperationDocumentForm onSubmit={addOperationDocument} /></Dialog>}
    {showNewCustomer && <Dialog title={editingCustomer ? "Editar cliente" : "Novo cliente"} onClose={() => { setEditingCustomer(null); setShowNewCustomer(false); }}><CustomerForm customer={editingCustomer} onSubmit={saveCustomer} onLookup={lookupCompany} onAddressLookup={lookupAddress} /></Dialog>}
  </div></CurrencyContext.Provider>;
}

function Dashboard({ operations, totalInProgress, totalValue, marketContext, marketContextError, locale, onOpen, onOpenChannel, userId, onOpenOperation, onOpenTask }: { operations: ImportOperation[]; totalInProgress: number; totalValue: number; marketContext: MarketContext | null; marketContextError: string; locale: Locale; onOpen: () => void; onOpenChannel: (channel: CustomsSignal) => void; userId: string; onOpenOperation: (id: string) => void; onOpenTask: (id: string) => void }) {
  const atPort = operations.filter((operation) => ["at_port", "customs"].includes(effectiveOperationStatus(operation))).length;
  const activeOperations = operations.filter((operation) => !["completed", "cleared"].includes(effectiveOperationStatus(operation)));
  const activeApproved = activeOperations.filter(hasApprovedBudget).length;
  const projectedApproved = operations.filter(hasApprovedBudget).reduce((sum, operation) => sum + calculateImport(operation).totalCost, 0);
  const projectedCosts = totalValue - projectedApproved;
  return <section className="page dashboard-page"><div className="page-heading"><div><p className="eyebrow">{t(locale, "controlCenter")}</p><h1>{t(locale, "operationsUnderControl")}</h1><p className="muted">{t(locale, "dashboardDescription")}</p></div><button className="button button--primary" onClick={onOpen}><ShipWheel size={18} /> {t(locale, "viewOperations")}</button></div>
    <div className="metric-grid"><Metric icon={<Container />} label={t(locale, "activeImports")} value={String(totalInProgress)} detail={<div className="metric-phase-counts"><span>{t(locale, "costsPhase")}: <b>{activeOperations.length - activeApproved}</b></span><span>{t(locale, "approvedPhase")}: <b>{activeApproved}</b></span></div>} tone="blue" /><Metric icon={<MapPinned />} label={t(locale, "cargoAtPort")} value={String(atPort)} detail={t(locale, "needsUpdate")} tone="amber" /><Metric icon={<ChartNoAxesCombined />} label={t(locale, "projectedCost")} value={money.format(projectedCosts)} monetaryValue={projectedCosts} detail={t(locale, "unapprovedCostsDetail")} tone="blue" /><Metric icon={<CheckCircle2 />} label={t(locale, "approvedCost")} value={money.format(projectedApproved)} monetaryValue={projectedApproved} detail={t(locale, "approvedCostsDetail")} tone="green" /></div>
    <CustomsSignalOverview operations={operations} locale={locale} onOpenChannel={onOpenChannel} />
    <div className="dashboard-grid"><section className="panel dashboard-recent-operations"><div className="panel-header"><div><h2>{t(locale, "recentOperations")}</h2><p>{t(locale, "recentOperationsDescription")}</p></div><button className="text-button" onClick={onOpen}>{t(locale, "viewOperations")}</button></div><div className="activity-list">{[...operations].sort((left, right) => (Date.parse(right.createdAt) || 0) - (Date.parse(left.createdAt) || 0)).slice(0, 5).map((operation) => <button className="activity-row" key={operation.id} onClick={() => onOpenOperation(operation.id)}><span className="activity-icon"><ShipWheel size={18} /></span><span><strong>{operation.reference}</strong><small>{operation.customer} · {operation.port || "Porto a definir"}</small></span><StatusBadge status={effectiveOperationStatus(operation)} /><ChevronRight size={18} /></button>)}</div></section>
      <MyTasks operations={operations} userId={userId} onOpen={onOpenTask} /></div>
    <LatestNews context={marketContext} error={marketContextError} locale={locale} />
  </section>;
}

function LatestNews({ context, error, locale }: { context: MarketContext | null; error: string; locale: Locale }) {
  if (!context && !error) return <section className="panel latest-news" aria-busy="true" aria-label={t(locale, "latestNews")}><div className="panel-header"><div><h2>{t(locale, "latestNews")}</h2><p>{t(locale, "officialNewsDescription")}</p></div></div><div className="news-grid news-grid--loading">{Array.from({ length: 3 }, (_, index) => <article key={index}><Skeleton className="skeleton--news-meta" /><Skeleton className="skeleton--news-title" /><Skeleton className="skeleton--news-line" /></article>)}</div></section>;
  if (error || !context?.news.length) return <section className="panel latest-news"><div className="panel-header"><div><h2>{t(locale, "latestNews")}</h2><p>{t(locale, "officialNewsDescription")}</p></div><a className="text-button" href="https://www.gov.br/siscomex/pt-br/noticias" target="_blank" rel="noreferrer">{t(locale, "openSiscomex")} <ExternalLink size={14} /></a></div><p className="news-empty">{t(locale, "newsUnavailable")}</p></section>;
  return <section className="panel latest-news"><div className="panel-header"><div><h2>{t(locale, "latestNews")}</h2><p>{t(locale, "officialNewsDescription")}</p></div><span className="news-updated">{t(locale, "updated")} {newsDate(context.updatedAt, locale)}</span></div><div className="news-grid">{context.news.slice(0, 6).map((news) => <a className="news-card" href={news.url} target="_blank" rel="noreferrer" key={`${news.source}-${news.url}`}><span><b>{news.source}</b><time dateTime={news.publishedAt}>{newsDate(news.publishedAt, locale)}</time></span><strong>{news.title}</strong><small>{t(locale, "readNews")} <ExternalLink size={13} aria-hidden="true" /></small></a>)}</div></section>;
}

function OperationsListView({ operations, urlState, onFiltersChange, onNew, onOpen }: { operations: ImportOperation[]; urlState: string; onFiltersChange: (filters: OperationsFilters) => void; onNew: () => void; onOpen: (id: string) => void }) {
  const [filters, setFiltersState] = useState<OperationsFilters>(operationsFiltersFromUrl);
  useEffect(() => { setFiltersState(operationsFiltersFromUrl()); }, [urlState]);
  const setFilters = (changes: Partial<OperationsFilters>) => { const next = { ...filters, ...changes }; setFiltersState(next); onFiltersChange(next); };
  const { query, status, channel, sort, page } = filters;
  const hasActiveFilters = Boolean(query) || status !== "all" || channel !== "all" || sort !== "oldest" || page > 1;
  const pageSize = 8;
  const filtered = operations.filter((operation) => (!query || `${operation.reference} ${operation.customer} ${operation.port}`.toLocaleLowerCase("pt-BR").includes(query.toLocaleLowerCase("pt-BR"))) && (status === "all" || effectiveOperationStatus(operation) === status) && (channel === "all" || operation.customsChannel === channel));
  const ordered = [...filtered].sort((a, b) => { const created = new Date(a.createdAt ?? a.updatedAt).getTime() - new Date(b.createdAt ?? b.updatedAt).getTime(); if (sort === "newest") return -created; if (sort === "updated") return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(); return created; });
  const totalPages = Math.max(1, Math.ceil(ordered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = ordered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return <section className="page operations-page"><div className="page-heading"><div><p className="eyebrow">GESTÃO DE IMPORTAÇÕES</p><h1>Operações</h1><p className="muted">Encontre uma operação, filtre a fila e abra um processo para trabalhar nos detalhes.</p></div><button className="button button--primary" onClick={onNew}><Plus size={18} /> Nova importação</button></div><section className="panel operations-list-panel"><div className="operations-toolbar"><label className="search-field"><Search size={17} /><input autoComplete="off" value={query} onChange={(event) => setFilters({ query: event.target.value, page: 1 })} placeholder="Buscar por referência, cliente ou porto" aria-label="Buscar operações" /></label><div className="operation-filters"><label><SlidersHorizontal size={15} /><span className="sr-only">Status</span><FieldSelect label="Status" value={status} onValueChange={(value) => setFilters({ status: value as ImportStatus | "all", page: 1 })}><SelectOption value="all">Todos os status</SelectOption>{Object.entries(importStatusMeta).map(([value, meta]) => <SelectOption key={value} value={value}>{meta.label}</SelectOption>)}</FieldSelect></label><label><span className="sr-only">Canal aduaneiro</span><FieldSelect label="Canal aduaneiro" value={channel} onValueChange={(value) => setFilters({ channel: value as CustomsSignal | "all", page: 1 })}><SelectOption value="all">Todos os canais</SelectOption>{Object.entries(customsChannelMeta).map(([value, meta]) => <SelectOption key={value} value={value}>{meta.label}</SelectOption>)}</FieldSelect></label><label><span className="sr-only">Ordenação</span><FieldSelect label="Ordenação" value={sort} onValueChange={(value) => setFilters({ sort: value as "oldest" | "newest" | "updated", page: 1 })}><SelectOption value="oldest">Mais antigas primeiro</SelectOption><SelectOption value="newest">Mais recentes primeiro</SelectOption><SelectOption value="updated">Atualizadas recentemente</SelectOption></FieldSelect></label></div><button type="button" className="text-button operation-filters__clear" disabled={!hasActiveFilters} onClick={() => setFilters({ query: "", status: "all", channel: "all", sort: "oldest", page: 1 })}>Limpar filtros</button></div><div className="table-scroll"><table className="operations-table"><thead><tr><th>Referência</th><th>Cliente</th><th>Destino</th><th>ETA</th><th>Fase</th><th>Status</th><th>Canal</th><th>Criada em</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{visible.length === 0 ? <tr><td className="empty-cell" colSpan={9}>Nenhuma operação corresponde aos filtros.</td></tr> : visible.map((operation) => <tr key={operation.id}><td><strong>{operation.reference}</strong></td><td>{operation.customer}</td><td><strong data-localized>{operation.port || translateUiText(activeLocale, "Porto a definir")}</strong><small>{operation.container}</small></td><td>{formatDate(operation.eta)}</td><td><OperationPhaseBadge operation={operation} /></td><td><StatusBadge status={effectiveOperationStatus(operation)} /></td><td><CustomsChannelIndicator channel={operation.customsChannel} /></td><td>{new Intl.DateTimeFormat(activeLocale, { dateStyle: "medium" }).format(new Date(operation.createdAt ?? operation.updatedAt))}</td><td><button className="table-detail-button" onClick={() => onOpen(operation.id)}>Ver detalhes <ChevronRight size={16} /></button></td></tr>)}</tbody></table></div><footer className="pagination"><span>{ordered.length === 0 ? "Nenhuma operação" : `${(currentPage - 1) * pageSize + 1}–${Math.min(currentPage * pageSize, ordered.length)} de ${ordered.length} operações`}</span><div><button className="icon-button" disabled={currentPage === 1} onClick={() => setFilters({ page: Math.max(1, currentPage - 1) })} aria-label="Página anterior"><ChevronLeft size={18} /></button><span>Página {currentPage} de {totalPages}</span><button className="icon-button" disabled={currentPage === totalPages} onClick={() => setFilters({ page: Math.min(totalPages, currentPage + 1) })} aria-label="Próxima página"><ChevronRight size={18} /></button></div></footer></section></section>;
}

function operationTimeline(operation: ImportOperation): OperationTimelineEntry[] {
  if (operation.timeline?.length) return operation.timeline;
  const status = importStatusMeta[effectiveOperationStatus(operation)];
  const portStatus = portStatusMeta[operation.portStatus] ?? portStatusMeta.awaiting_departure;
  return [
    { id: "created", title: "Operação criada", description: "Processo aberto para acompanhamento operacional.", occurredAt: validDate(operation.createdAt).toISOString(), type: "milestone" },
    { id: "current-status", title: status.label, description: portStatus.detail, occurredAt: validDate(operation.updatedAt).toISOString(), type: "status" }
  ];
}
function validDate(value?: string) { const date = value ? new Date(value) : new Date(); return Number.isNaN(date.getTime()) ? new Date() : date; }
function operationTasks(operation: ImportOperation): OperationTask[] {
  if (operation.tasks) return operation.tasks;
  return [{ id: "initial-task", title: "Revisar documentação da operação", assignee: "Operação", dueDate: operation.eta, completed: false, createdAt: operation.createdAt }];
}
function dayLabel(value?: string) { return value ? new Intl.DateTimeFormat(activeLocale, { day: "2-digit", month: "short" }).format(new Date(`${value.slice(0, 10)}T12:00:00`)) : "Sem prazo"; }

function OperationDetailPage({ selected, onBack, onAddItem, onImportProducts, onEditItem, onRemoveItem, onAddTimeline, onAddTask, onEditTask, onRemoveTask, onApproveCosts, onAddDocument, onToggleTask, onEditPort, onUpdate, users, usersLoading }: { selected: ImportOperation; onBack: () => void; onAddItem: () => void; onImportProducts: () => void; onEditItem: (item: ImportItem) => void; onRemoveItem: (item: ImportItem) => void; onAddTimeline: () => void; onAddTask: () => void; onEditTask: (task: OperationTask) => void; onRemoveTask: (task: OperationTask) => void; onApproveCosts: () => void; onAddDocument: () => void; onToggleTask: (taskId: string) => void; onEditPort: () => void; onUpdate: (id: string, changes: Partial<ImportOperation>) => void; users: SessionUser[]; usersLoading: boolean }) {
  const calculated = calculateImport(selected);
  const timeline = operationTimeline(selected);
  const tasks = operationTasks(selected);
  const documents = selected.documents ?? [];
  const { rates, loading: currencyLoading } = useCurrency();
  const reportContext = { timeline, tasks, documents, rates, users };
  const [exporting, setExporting] = useState<"xlsx" | "pdf" | null>(null);
  const [exportError, setExportError] = useState("");
  const exportReport = async (format: "xlsx" | "pdf") => { setExporting(format); setExportError(""); try { const { downloadOperationPdf, downloadOperationXlsx } = await import("./lib/operation-report"); if (format === "xlsx") await downloadOperationXlsx(selected, reportContext); else await downloadOperationPdf(selected, reportContext); } catch (error) { setExportError(error instanceof Error ? error.message : "Não foi possível gerar o relatório."); } finally { window.setTimeout(() => setExporting(null), 350); } };
  return <section className="page operations-page operation-detail-page"><div className="detail-heading"><button className="back-button" onClick={onBack}><ArrowLeft size={17} /> Todas as operações</button><div className="detail-heading__actions"><p className="eyebrow">DETALHE DA OPERAÇÃO</p><div><button className="button button--secondary" onClick={() => exportReport("xlsx")} disabled={exporting !== null || currencyLoading}><Download size={16} /> {exporting === "xlsx" ? "Gerando XLSX…" : "Exportar XLSX"}</button><button className="button button--primary" onClick={() => exportReport("pdf")} disabled={exporting !== null || currencyLoading}><FileBarChart size={16} /> {exporting === "pdf" ? "Gerando PDF…" : "Exportar PDF"}</button></div></div>{exportError && <p className="export-error" role="alert">{exportError}</p>}</div><OperationPhaseHeader operation={selected} onApprove={onApproveCosts} /><OperationHeader operation={selected} onEditPort={onEditPort} onUpdate={onUpdate} users={users} usersLoading={usersLoading} /><div className="summary-grid"><Summary emphasis="primary" label="Custo total projetado" value={money.format(calculated.totalCost)} monetaryValue={calculated.totalCost} detail="estimativa atual da operação" /><Summary label="Pendências abertas" value={String(tasks.filter((task) => !task.completed).length)} detail="tarefas para concluir" /><Summary label="Documentos" value={String(documents.length)} detail={`${documents.filter((document) => document.status === "available").length} disponíveis`} /></div><section id="tasks" className="panel tasks-panel"><div className="panel-header"><div><h2>Pendências</h2><p>Controle de responsáveis e prazos.</p></div><button className="button button--secondary" onClick={onAddTask}><Plus size={17} /> Nova pendência</button></div><OperationTasks tasks={tasks} onEdit={onEditTask} onRemove={onRemoveTask} onToggle={onToggleTask} users={users} usersLoading={usersLoading} /></section><section id="documents" className="panel documents-panel"><div className="panel-header"><div><h2>Documentos</h2><p>Referências, validade e disponibilidade da documentação do processo.</p></div><button className="button button--secondary" onClick={onAddDocument}><Upload size={17} /> Registrar documento</button></div><OperationDocuments documents={documents} /></section><section className="panel"><div className="panel-header"><div><h2>Produtos da importação</h2><p>O custo unitário já inclui rateio e tributos.</p></div><div className="product-panel-actions"><button className="button button--secondary" onClick={onImportProducts}><Upload size={17} /> Importar planilha</button><button className="button button--secondary" onClick={onAddItem}><PackagePlus size={17} /> Adicionar item</button></div></div><ProductsTable key={selected.id} calculated={calculated} onEdit={onEditItem} onRemove={onRemoveItem} /></section><CostsForm operation={selected} calculated={calculated} onUpdate={onUpdate} /><ItemPricingPanel calculated={calculated} onEdit={onEditItem} /><section id="timeline" className="panel timeline-panel"><div className="panel-header"><div><h2>Linha do tempo</h2><p>Marcos e atualizações registrados na operação.</p></div><button className="button button--secondary" onClick={onAddTimeline}><Plus size={17} /> Registrar marco</button></div><OperationTimeline key={selected.id} entries={timeline} /></section></section>;
}

function OperationTimeline({ entries }: { entries: OperationTimelineEntry[] }) { const locale = useLocale(); const [page, setPage] = useState(1); const pageSize = 5; const ordered = [...entries].sort((left, right) => validDate(right.occurredAt).getTime() - validDate(left.occurredAt).getTime()); const pageCount = Math.max(1, Math.ceil(ordered.length / pageSize)); const currentPage = Math.min(page, pageCount); const first = (currentPage - 1) * pageSize; const newestId = ordered[0]?.id; useEffect(() => { setPage(1); }, [entries.length, newestId]); const text = (value: string) => translateUiText(locale, value); return <><ol className="operation-timeline" start={first + 1}>{ordered.slice(first, first + pageSize).map((entry) => { const occurredAt = validDate(entry.occurredAt); const recordedAt = validDate(entry.recordedAt ?? entry.occurredAt); return <li key={entry.id} data-type={entry.type}><span><CalendarClock size={15} /></span><div><time dateTime={occurredAt.toISOString()}>{new Intl.DateTimeFormat(activeLocale, { dateStyle: "medium", timeStyle: "short" }).format(occurredAt)}</time><strong>{entry.title}</strong>{entry.description && <p>{entry.description}</p>}<small className="timeline-author">Registrado por {entry.actorName || "Sistema"} · {new Intl.DateTimeFormat(activeLocale, { dateStyle: "short", timeStyle: "short" }).format(recordedAt)}</small></div></li>; })}</ol><div className="timeline-pagination-footer" data-localized><span className="timeline-pagination__summary">{locale === "en-US" ? `${ordered.length ? first + 1 : 0}–${Math.min(first + pageSize, ordered.length)} of ${ordered.length} events` : locale === "zh-CN" ? `第 ${ordered.length ? first + 1 : 0}–${Math.min(first + pageSize, ordered.length)} 条，共 ${ordered.length} 条记录` : `${ordered.length ? first + 1 : 0}–${Math.min(first + pageSize, ordered.length)} de ${ordered.length} registros`}</span><Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} label={text("Paginação da linha do tempo")} previousLabel={text("Anterior")} nextLabel={text("Próxima")} pageLabel={text(`Página ${currentPage} de ${pageCount}`)} /></div></>; }
function OperationTasks({ tasks, onToggle, onEdit, onRemove, users, usersLoading }: { tasks: OperationTask[]; onToggle: (taskId: string) => void; onEdit: (task: OperationTask) => void; onRemove: (task: OperationTask) => void; users: SessionUser[]; usersLoading: boolean }) {
  const locale = useLocale();
  const ordered = [...tasks].sort((left, right) => Number(left.completed) - Number(right.completed) || (left.dueDate ?? "9999").localeCompare(right.dueDate ?? "9999"));
  return <div className="operation-tasks" data-localized>{!ordered.length && <p className="tasks-empty">{translateUiText(locale, "Nenhuma pendência cadastrada.")}</p>}{ordered.map((task) => {
    const user = task.assigneeId ? users.find((member) => member.id === task.assigneeId) : users.find((member) => member.name === task.assignee);
    const name = user?.name || task.assignee;
    return <div className={task.completed ? "is-completed" : ""} key={task.id}>
      <button type="button" onClick={() => onToggle(task.id)} aria-label={`${translateUiText(locale, task.completed ? "Reabrir" : "Concluir")} ${task.title}`}>{task.completed ? <CheckCircle2 size={18} /> : <span />}</button>
      <span><strong>{task.title}</strong><small className="task-assignee">{usersLoading && task.assigneeId ? <Skeleton className="task-assignee__skeleton" /> : name ? <><UserAvatar user={user || { name }} /><span>{name}</span></> : <span>{translateUiText(locale, "Sem responsável")}</span>}<span>· {dayLabel(task.dueDate)}</span></small></span>
      <div className="task-actions">{!task.completed && task.dueDate && <b>{dayLabel(task.dueDate)}</b>}<Button className="table-action" onClick={() => onEdit(task)} aria-label={`${translateUiText(locale, "Editar pendência")} ${task.title}`}><Pencil size={16} /></Button><Button className="table-action table-action--danger" onClick={() => onRemove(task)} aria-label={`${translateUiText(locale, "Excluir pendência")} ${task.title}`}><Trash2 size={16} /></Button></div>
    </div>;
  })}</div>;
}
function OperationDocuments({ documents }: { documents: OperationDocument[] }) { if (!documents.length) return <div className="documents-empty"><FileText size={22} /><p>Registre os documentos recebidos para acompanhar validade e disponibilidade.</p></div>; return <div className="table-scroll"><table className="documents-table"><thead><tr><th>Documento</th><th>Referência</th><th>Emissão</th><th>Validade</th><th>Situação</th></tr></thead><tbody>{documents.map((document) => <tr key={document.id}><td><strong>{document.title}</strong><small>{document.type}</small></td><td>{document.reference || "—"}</td><td>{dayLabel(document.issuedAt)}</td><td>{dayLabel(document.expiresAt)}</td><td><span className={`document-status document-status--${document.status}`}>{document.status === "available" ? "Disponível" : document.status === "expired" ? "Vencido" : "Pendente"}</span></td></tr>)}</tbody></table></div>; }
function OperationContainerField({ operation, onUpdate }: { operation: ImportOperation; onUpdate: (id: string, changes: Partial<ImportOperation>) => void }) {
  const locale = useLocale();
  const approved = hasApprovedBudget(operation);
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(operation.container || "");
  useEffect(() => { setValue(operation.container || ""); }, [operation.container]);
  useEffect(() => { if (!approved) setEditing(false); }, [approved]);
  const text = (source: string) => translateUiText(locale, source);
  return <div className="operation-container" data-localized>
    {editing && approved ? <form autoComplete="off" className="operation-container__form" onSubmit={(event) => { event.preventDefault(); if (!hasApprovedBudget(operation)) return; onUpdate(operation.id, { container: value.trim().toUpperCase() }); setEditing(false); }}>
      <label className="field"><span>{text("Contêiner")}</span><Input autoFocus name="container" value={value} onChange={(event) => setValue(event.target.value)} placeholder="ABCD 123456-7" /></label>
      <div className="operation-container__actions"><Button className="button button--primary" type="submit"><Check size={16} />{text("Salvar")}</Button><Button className="button button--secondary" onClick={() => { setValue(operation.container || ""); setEditing(false); }}>{text("Cancelar")}</Button></div>
    </form> : <><span className="operation-container__label">{text("Contêiner")}</span><div className="operation-container__value"><strong>{operation.container || text("Não informado")}</strong>{approved && <Button className="text-button" onClick={() => setEditing(true)}><Pencil size={15} />{text(operation.container ? "Editar contêiner" : "Definir contêiner")}</Button>}</div>{!approved && <small>{text("Disponível após aprovação dos custos.")}</small>}</>}
  </div>;
}

function OperationPhaseBadge({ operation }: { operation: ImportOperation }) {
  const locale = useLocale();
  const approved = hasApprovedBudget(operation);
  return <span data-localized className={`operation-phase-badge ${approved ? "is-approved" : "is-costs"}`}>{approved ? <CheckCircle2 size={15} aria-hidden="true" /> : <FileText size={15} aria-hidden="true" />}{translateUiText(locale, approved ? "Aprovado" : "Custos")}</span>;
}
function OperationPhaseHeader({ operation, onApprove }: { operation: ImportOperation; onApprove: () => void }) {
  const locale = useLocale();
  const approved = hasApprovedBudget(operation);
  const ready = calculateImport(operation).calculationReady;
  const budget = operation.budgets?.find((entry) => entry.status === "approved");
  const approvedDate = budget?.approvedAt ? new Date(budget.approvedAt) : null;
  // Legacy approvals may only identify their author in the matching timeline event.
  const approvalEvent = approvedDate && !Number.isNaN(approvedDate.getTime()) ? operation.timeline?.find((entry) => ["Orçamento aprovado", "Custos aprovados"].includes(entry.title) && Math.abs(Date.parse(entry.occurredAt) - approvedDate.getTime()) <= 1000) : undefined;
  const approvedBy = budget?.approvedBy?.trim() || approvalEvent?.actorName?.trim();
  return <section className={`operation-phase-header ${approved ? "is-approved" : "is-costs"}`} data-localized aria-label={translateUiText(locale, "Fase da importação")}>
    <div><OperationPhaseBadge operation={operation} /><h2>{translateUiText(locale, approved ? "Custos aprovados" : "Custos da importação")}</h2><p>{translateUiText(locale, approved ? "Acompanhe o embarque, a chegada e as despesas realizadas." : "Prepare a estimativa e aprove os custos para iniciar o acompanhamento da importação.")}</p>{approved && <small>{translateUiText(locale, "Aprovado por")} <b>{approvedBy || translateUiText(locale, "Usuário não registrado")}</b> · {approvedDate && !Number.isNaN(approvedDate.getTime()) ? <time dateTime={approvedDate.toISOString()}>{new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short", timeZone: "America/Sao_Paulo" }).format(approvedDate)}</time> : translateUiText(locale, "Data não registrada")}</small>}</div>
    {!approved && <div className="operation-phase-header__action"><Button className="button button--primary" onClick={onApprove} disabled={!operation.items.length || !ready}><CheckCircle2 size={18} />{translateUiText(locale, "Aprovar Custos")}</Button>{!ready && operation.items.length > 0 && <small>{translateUiText(locale, "Revise os alertas da estimativa antes de aprovar.")}</small>}{!operation.items.length && <small>{translateUiText(locale, "Adicione produtos antes de aprovar os custos.")}</small>}</div>}
  </section>;
}
function operationBudget(operation: ImportOperation): ImportBudget {
  return { ...newBudget(operation.exchangeRate), calculationModel: "legacy", marginMethod: "sale_margin", expenses: [
    { id: uid("expense"), category: "Frete", kind: "freight", label: "Frete internacional", amount: operation.freightBrl, currency: "BRL", allocationMethod: "fob", status: "estimated" },
    { id: uid("expense"), category: "Seguro", kind: "insurance", label: "Seguro internacional", amount: operation.insuranceBrl, currency: "BRL", allocationMethod: "fob", status: "estimated" },
    { id: uid("expense"), category: "Porto", label: "Despesas portuárias", amount: operation.portExpensesBrl, currency: "BRL", allocationMethod: "fob", status: "estimated" }
  ] };
}
function OperationHeader({ operation, onEditPort, onUpdate, users, usersLoading }: { operation: ImportOperation; onEditPort: () => void; onUpdate: (id: string, changes: Partial<ImportOperation>) => void; users: SessionUser[]; usersLoading: boolean }) {
  const approved = hasApprovedBudget(operation);
  const assignedUser = users.find((item) => item.id === operation.assigneeId);
  const assign = (value: string) => { const user = users.find((item) => item.id === value); onUpdate(operation.id, { assigneeId: user?.id, assigneeName: user?.name }); };
  return <header className="operation-header panel"><div><p className="eyebrow">{operation.reference}</p><h2>{operation.customer}</h2><OperationContainerField key={operation.id} operation={operation} onUpdate={onUpdate} /></div><div className="operation-status"><label>Status da operação<FieldSelect label="Status da operação" value={effectiveOperationStatus(operation)} onValueChange={(value) => onUpdate(operation.id, { status: value as ImportStatus })}>{operationStatusOptions(operation).map((value) => <SelectOption value={value} key={value}>{importStatusMeta[value].label}</SelectOption>)}</FieldSelect></label></div><div className="operation-assignee"><span>Responsável</span>{usersLoading ? <Skeleton className="skeleton--input" /> : <Select value={operation.assigneeId ?? "unassigned"} onValueChange={assign}><SelectTrigger className="operation-assignee__select" aria-label="Responsável pela importação"><SelectValue>{assignedUser ? <span className="assignee-option"><UserAvatar user={assignedUser} /><span>{assignedUser.name}</span></span> : <span className="assignee-option assignee-option--empty"><UserRound aria-hidden="true" /><span>Sem responsável</span></span>}</SelectValue></SelectTrigger><SelectContent className="operation-assignee__content" sideOffset={6}><SelectItem value="unassigned" hideIndicator><span className="assignee-option assignee-option--empty"><UserRound aria-hidden="true" /><span>Sem responsável</span></span></SelectItem>{users.map((user) => <SelectItem value={user.id} key={user.id} hideIndicator><span className="assignee-option"><UserAvatar user={user} /><span>{user.name}</span></span></SelectItem>)}</SelectContent></Select>}<small>{assignedUser ? "Pessoa responsável pelo acompanhamento desta importação." : "Atribua uma pessoa para acompanhar esta importação."}</small></div><div className="port-progress"><div><span className="port-pin"><MapPinned size={18} /></span><span><strong data-localized>{operation.port || translateUiText(activeLocale, "Porto a definir")}</strong><small>ETA {formatDate(operation.eta)}</small><Button data-localized className="text-button" onClick={onEditPort}>{translateUiText(activeLocale, operation.port ? "Alterar porto" : "Definir porto")}</Button></span></div><label>Status portuário<FieldSelect label="Status portuário" disabled={!approved} value={operation.portStatus} onValueChange={(value) => onUpdate(operation.id, { portStatus: value as PortStatus })}>{Object.entries(portStatusMeta).map(([value, meta]) => <SelectOption value={value} key={value}>{meta.label}</SelectOption>)}</FieldSelect></label></div><div className="customs-channel-row"><CustomsLight channel={operation.customsChannel} /><div><strong>Canal aduaneiro</strong><p>{customsChannelMeta[operation.customsChannel].detail}</p></div><label><span className="sr-only">Canal aduaneiro</span><FieldSelect label="Canal aduaneiro" disabled={!approved} value={operation.customsChannel} onValueChange={(value) => onUpdate(operation.id, { customsChannel: value as CustomsSignal })}>{Object.entries(customsChannelMeta).map(([value, meta]) => <SelectOption value={value} key={value}>{meta.label}</SelectOption>)}</FieldSelect><small>Atualização manual</small></label></div></header>;
}

function CustomsLight({ channel, compact = false, active = true, allColors = false }: { channel: CustomsSignal; compact?: boolean; active?: boolean; allColors?: boolean }) { const locale = useLocale(); const meta = customsChannelMeta[channel]; return <div className={`customs-light${compact ? " customs-light--compact" : ""}`} role="img" data-localized aria-label={allColors ? `${t(locale, "customsLight")}: ${["greenChannel", "yellowChannel", "redChannel", "grayChannel"].map((key) => t(locale, key as Parameters<typeof t>[1])).join(", ")}` : active ? `${translateUiText(locale, meta.label)}: ${translateUiText(locale, meta.detail)}` : t(locale, "customsLight")}><span className="customs-light__lens customs-light__lens--green" data-active={active && (allColors || channel === "green")} /><span className="customs-light__lens customs-light__lens--yellow" data-active={active && (allColors || channel === "yellow")} /><span className="customs-light__lens customs-light__lens--red" data-active={active && (allColors || channel === "red")} /><span className="customs-light__lens customs-light__lens--gray" data-active={active && (allColors || channel === "gray" || channel === "unassigned")} /></div>; }

function CustomsChannelIndicator({ channel }: { channel: CustomsSignal }) { const meta = customsChannelMeta[channel]; if (channel === "unassigned") return <span data-localized aria-label={translateUiText(activeLocale, "Sem canal")} title={translateUiText(activeLocale, "Sem canal")}>-</span>; return <span className={`customs-channel-indicator customs-channel-indicator--${channel}`} title={`${meta.label}: ${meta.detail}`}><span aria-hidden="true" /><span>{meta.label.replace("Canal ", "")}</span></span>; }

function CustomsSignalOverview({ operations, locale, onOpenChannel }: { operations: ImportOperation[]; locale: Locale; onOpenChannel: (channel: CustomsSignal) => void }) { const channels: CustomsChannel[] = ["green", "yellow", "red", "gray"]; const signals: CustomsSignal[] = ["unassigned", ...channels]; const counts = Object.fromEntries(signals.map((channel) => [channel, operations.filter((operation) => operation.customsChannel === channel).length])) as Record<CustomsSignal, number>; const unassigned = counts.unassigned; const labels: Record<CustomsSignal, [Parameters<typeof t>[1], Parameters<typeof t>[1]]> = { unassigned: ["noChannel", "noChannelDefined"], green: ["greenChannel", "automaticClearance"], yellow: ["yellowChannel", "documentInspection"], red: ["redChannel", "documentPhysicalInspection"], gray: ["grayChannel", "fraudInvestigation"] }; return <section className="panel customs-overview"><div className="customs-overview__intro"><CustomsLight channel="unassigned" allColors /><div><h2>{t(locale, "customsLight")}</h2><p>{t(locale, "customsDescription")}</p>{unassigned > 0 && <small>{unassigned} {t(locale, "noChannelDefined")}</small>}</div></div><div className="customs-overview__counts"><button className="customs-count customs-count--unassigned" type="button" onClick={() => onOpenChannel("unassigned")} aria-label={t(locale, "noChannel")}><span className="customs-count__dot" aria-hidden="true" /><span>{t(locale, labels.unassigned[0])}</span><strong>{unassigned}</strong><small>{t(locale, labels.unassigned[1])}</small></button>{channels.map((channel) => { const count = counts[channel]; return <button className={`customs-count customs-count--${channel}`} type="button" key={channel} onClick={() => onOpenChannel(channel)} aria-label={t(locale, labels[channel][0])}><span className="customs-count__dot" aria-hidden="true" /><span>{t(locale, labels[channel][0])}</span><strong>{count}</strong><small>{t(locale, labels[channel][1])}</small></button>; })}</div></section>; }

function PortsCatalogView({ facilities, state, error, onRetry }: { facilities: PortFacility[]; state: "idle" | "loading" | "ready" | "error"; error: string; onRetry: () => void }) {
  const [query, setQuery] = useState("");
  const [selectedState, setSelectedState] = useState("all");
  const [selectedType, setSelectedType] = useState("all");
  const [page, setPage] = useState(1);
  const pageSize = 12;
  const states = [...new Set(facilities.map((facility) => facility.state))].sort();
  const types = [...new Set(facilities.map((facility) => facility.type))].sort();
  const filtered = facilities.filter((facility) => (!query || `${facility.name} ${facility.municipality} ${facility.state}`.toLocaleLowerCase("pt-BR").includes(query.toLocaleLowerCase("pt-BR"))) && (selectedState === "all" || facility.state === selectedState) && (selectedType === "all" || facility.type === selectedType));
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const resetPage = () => setPage(1);

  return <section className="page ports-catalog-page"><div className="page-heading"><div><p className="eyebrow">DADOS DE REFERÊNCIA</p><h1>Instalações portuárias</h1><p className="muted">Catálogo oficial para padronizar portos e terminais nas operações de importação.</p></div><a className="button button--secondary" href="https://www.gov.br/antaq/pt-br/assuntos/instalacoes-portuarias" target="_blank" rel="noreferrer">Fonte: ANTAQ</a></div><section className="panel ports-catalog-panel"><div className="ports-catalog-context"><span><MapPinned size={18} aria-hidden="true" /><strong>{facilities.length || "—"}</strong> instalações publicadas</span><span>Referência administrativa; o andamento da carga é registrado dentro de cada operação.</span></div><div className="operations-toolbar ports-toolbar"><label className="search-field"><Search size={17} aria-hidden="true" /><input autoComplete="off" value={query} onChange={(event) => { setQuery(event.target.value); resetPage(); }} placeholder="Buscar por instalação, cidade ou UF" aria-label="Buscar instalações portuárias" /></label><div className="operation-filters"><label><span className="sr-only">UF</span><FieldSelect label="Estado" value={selectedState} onValueChange={(value) => { setSelectedState(value); resetPage(); }}><SelectOption value="all">Todas as UFs</SelectOption>{states.map((item) => <SelectOption value={item} key={item}>{item}</SelectOption>)}</FieldSelect></label><label><span className="sr-only">Tipo</span><FieldSelect label="Tipo de instalação" value={selectedType} onValueChange={(value) => { setSelectedType(value); resetPage(); }}><SelectOption value="all">Todos os tipos</SelectOption>{types.map((item) => <SelectOption value={item} key={item}>{item}</SelectOption>)}</FieldSelect></label></div></div>{state === "loading" && <div className="table-scroll" aria-busy="true" aria-label="Carregando catálogo de instalações portuárias"><table className="ports-table"><thead><tr><th>Instalação</th><th>Localização</th><th>Tipo</th><th>Gestão</th><th>Situação</th></tr></thead><tbody><TableSkeletonRows columns={5} rows={8} /></tbody></table></div>}{state === "error" && <div className="catalog-message catalog-message--error" role="alert"><span>{error}</span><button className="button button--secondary" onClick={onRetry}>Tentar novamente</button></div>}{state === "ready" && <><div className="table-scroll"><table className="ports-table"><thead><tr><th>Instalação</th><th>Localização</th><th>Tipo</th><th>Gestão</th><th>Situação</th></tr></thead><tbody>{visible.length === 0 ? <tr><td className="empty-cell" colSpan={5}>Nenhuma instalação corresponde aos filtros.</td></tr> : visible.map((facility) => <tr key={facility.id}><td><strong>{facility.name}</strong><small>ID ANTAQ {facility.id}</small></td><td><strong>{facility.municipality}</strong><small>{facility.state}</small></td><td><span className="facility-type">{facility.type}</span></td><td>{facility.management || "Não informado"}</td><td><span className="facility-status">{facility.operationalStatus || "Não informado"}</span></td></tr>)}</tbody></table></div><footer className="pagination"><span>{filtered.length === 0 ? "Nenhuma instalação" : `${(currentPage - 1) * pageSize + 1}–${Math.min(currentPage * pageSize, filtered.length)} de ${filtered.length} instalações`}</span><div><button className="icon-button" disabled={currentPage === 1} onClick={() => setPage((value) => Math.max(1, value - 1))} aria-label="Página anterior"><ChevronLeft size={18} /></button><span>Página {currentPage} de {totalPages}</span><button className="icon-button" disabled={currentPage === totalPages} onClick={() => setPage((value) => Math.min(totalPages, value + 1))} aria-label="Próxima página"><ChevronRight size={18} /></button></div></footer></>}</section></section>;
}

function ProductsTable({ calculated, onEdit, onRemove }: { calculated: ReturnType<typeof calculateImport>; onEdit: (item: ImportItem) => void; onRemove: (item: ImportItem) => void }) {
  const locale = useLocale();
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState<ProductSort>("original");
  const [dataFilter, setDataFilter] = useState<ProductDataFilter>("all");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const expenses = calculated.budget?.expenses;
  const incompleteCount = calculated.items.filter((item) => missingProductFields(item, expenses, calculated.budget?.calculationModel === "worksheet").length > 0).length;
  const filtered = useMemo(() => selectProducts(calculated.items, query, sort, locale).filter((item) => matchesProductDataFilter(item, dataFilter, expenses, calculated.budget?.calculationModel === "worksheet")), [calculated.items, query, sort, locale, dataFilter, expenses]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  useEffect(() => { setPage((current) => Math.min(current, pageCount)); }, [pageCount]);
  const start = (currentPage - 1) * pageSize;
  const visibleItems = filtered.slice(start, start + pageSize);
  const sortOptions: [ProductSort, string][] = [
    ["original", "Ordem de cadastro"], ["name_asc", "Nome: A a Z"], ["name_desc", "Nome: Z a A"],
    ["quantity_desc", "Maior quantidade"], ["quantity_asc", "Menor quantidade"],
    ["fob_desc", "Maior FOB"], ["fob_asc", "Menor FOB"], ["taxes_desc", "Maiores tributos"], ["taxes_asc", "Menores tributos"],
    ["unit_cost_desc", "Maior custo unitário"], ["unit_cost_asc", "Menor custo unitário"]
  ];
  return <div className="products-list" data-localized>
    <div className="products-toolbar">
      <label className="search-field"><Search size={17} aria-hidden="true" /><Input value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} aria-label={translateUiText(locale, "Buscar produtos")} placeholder={translateUiText(locale, "Nome, SKU ou NCM")} /></label>
      <label className="field products-data-filter"><span>{translateUiText(locale, "Preenchimento")}</span><FieldSelect label="Preenchimento dos produtos" value={dataFilter} onValueChange={(value) => { setDataFilter(value as ProductDataFilter); setPage(1); }}><SelectOption value="all">Todos os produtos</SelectOption><SelectOption value="incomplete">Dados incompletos</SelectOption><SelectOption value="complete">Dados completos</SelectOption></FieldSelect></label>
      <label className="field"><span>{translateUiText(locale, "Ordenar")}</span><FieldSelect label="Ordenar produtos" value={sort} onValueChange={(value) => { setSort(value as ProductSort); setPage(1); }}>{sortOptions.map(([value, label]) => <SelectOption key={value} value={value}>{label}</SelectOption>)}</FieldSelect></label>
      <label className="field products-page-size"><span>{translateUiText(locale, "Por página")}</span><FieldSelect label="Produtos por página" value={String(pageSize)} onValueChange={(value) => { setPageSize(Number(value)); setPage(1); }}>{[10, 25, 50, 100].map((value) => <SelectOption value={String(value)} key={value}>{String(value)}</SelectOption>)}</FieldSelect></label>
      <Button type="button" className="text-button" disabled={!query && sort === "original" && dataFilter === "all"} onClick={() => { setQuery(""); setSort("original"); setDataFilter("all"); setPage(1); }}>{translateUiText(locale, "Limpar filtros")}</Button>
    </div>
    <p className="products-completeness-summary" aria-live="polite">{incompleteCount} {translateUiText(locale, "com dados incompletos")}</p>
    <div className="table-scroll"><table><thead><tr><th>{translateUiText(locale, "Produto / NCM")}</th><th>{translateUiText(locale, "Qtd.")}</th><th>{translateUiText(locale, calculated.budget?.calculationModel === "worksheet" && calculated.budget.priceBasis === "cif" ? "CIF" : "FOB")}</th><th>{translateUiText(locale, "Rateio")}</th><th>{translateUiText(locale, "Tributos")}</th><th>{translateUiText(locale, "Custo unitário")}</th><th><span className="sr-only">{translateUiText(locale, "Ações")}</span></th></tr></thead><tbody>{visibleItems.length === 0 ? <tr><td colSpan={7} className="empty-cell">{calculated.items.length === 0 ? translateUiText(locale, "Adicione os produtos para calcular os custos.") : translateUiText(locale, "Nenhum produto encontrado.")}</td></tr> : visibleItems.map((item) => <tr key={item.id}><td><strong>{item.name || translateUiText(activeLocale, "Nome em português pendente")}</strong>{item.chineseName && <small lang="zh">{item.chineseName}</small>}<small>{item.ncm}</small><ProductMissingData fields={missingProductFields(item, expenses, calculated.budget?.calculationModel === "worksheet")} /></td><td>{item.quantity}</td><td><MoneyAmount value={item.itemFob} /></td><td><MoneyAmount value={item.allocatedExpenses} /></td><td><MoneyAmount value={item.taxes} /></td><td><strong><MoneyAmount value={item.unitCost} /></strong></td><td><span className="product-actions"><button className="table-action" type="button" onClick={() => onEdit(item)} aria-label={`${translateUiText(locale, "Editar")} ${item.name || item.chineseName || translateUiText(locale, "produto")}`}><Pencil size={16} /></button><button className="table-action table-action--danger" type="button" onClick={() => onRemove(item)} aria-label={`${translateUiText(locale, "Remover")} ${item.name || item.chineseName || translateUiText(locale, "produto")}`}><Trash2 size={16} /></button></span></td></tr>)}</tbody></table></div>
    <footer className="products-pagination"><span aria-live="polite">{filtered.length ? `${start + 1}–${Math.min(start + pageSize, filtered.length)}` : "0"} / {filtered.length} {translateUiText(locale, filtered.length === 1 ? "produto" : "produtos")}</span><Pagination page={currentPage} pageCount={pageCount} onPageChange={setPage} label={translateUiText(locale, "Paginação dos produtos")} previousLabel={translateUiText(locale, "Anterior")} nextLabel={translateUiText(locale, "Próxima")} pageLabel={`${translateUiText(locale, "Página")} ${currentPage} / ${pageCount}`} /></footer>
  </div>;
}

function ProductMissingData({ fields }: { fields: MissingProductField[] }) {
  const locale = useLocale();
  const labels: Record<MissingProductField, string> = { name: "Nome em português", ncm: "NCM (8 dígitos)", quantity: "Quantidade", price: "Preço unitário (US$)", weight: "Peso para rateio", volume: "Volume para rateio", ii: "II (%)", ipi: "IPI (%)" };
  if (!fields.length) return null;
  return <small className="product-missing-data"><CircleHelp size={14} aria-hidden="true" /><span>{translateUiText(locale, "Faltam dados")}: {fields.map((field) => translateUiText(locale, labels[field])).join(", ")}</span></small>;
}
export function CostsForm({ operation, calculated, onUpdate }: { operation: ImportOperation; calculated: ReturnType<typeof calculateImport>; onUpdate: (id: string, changes: Partial<ImportOperation>, audit?: { title: string; description?: string; type: OperationTimelineEntry["type"] }) => void }) {
  const [mode, setMode] = useState<"budget" | "actual">("budget");
  const approved = hasApprovedBudget(operation);
  useEffect(() => { setMode("budget"); }, [operation.id, approved]);
  const budget = calculated.budget;
  const actualTotal = calculateActualExpenses(operation);
  const ensureBudget = () => onUpdate(operation.id, { budgets: [...(operation.budgets ?? []), operationBudget(operation)] }, { title: "Orçamento estruturado criado", description: "Os valores existentes foram convertidos em despesas estimadas do orçamento.", type: "milestone" });
  const saveBudget = (next: ImportBudget, audit?: { title: string; description?: string; type: OperationTimelineEntry["type"] }) => onUpdate(operation.id, { budgets: (operation.budgets ?? []).map((candidate) => candidate.id === next.id ? next : candidate) }, audit);
  const addExpense = (actual = false) => {
    const expense: ImportExpense = { id: uid("expense"), category: actual ? "Realizado" : "Logística", label: actual ? "Novo custo realizado" : "Nova despesa estimada", amount: 0, currency: "BRL", allocationMethod: "fob", status: actual ? "invoiced" : "estimated" };
    if (actual) onUpdate(operation.id, { actualExpenses: [...(operation.actualExpenses ?? []), expense] });
    else if (budget) saveBudget({ ...budget, expenses: [...budget.expenses, expense] });
  };
  const updateExpense = (id: string, changes: Partial<ImportExpense>, actual = false) => {
    if (actual) onUpdate(operation.id, { actualExpenses: (operation.actualExpenses ?? []).map((expense) => expense.id === id ? { ...expense, ...changes } : expense) });
    else if (budget) saveBudget({ ...budget, expenses: budget.expenses.map((expense) => expense.id === id ? { ...expense, ...changes } : expense) });
  };
  const removeExpense = (id: string, actual = false) => {
    if (actual) onUpdate(operation.id, { actualExpenses: (operation.actualExpenses ?? []).filter((expense) => expense.id !== id) });
    else if (budget) saveBudget({ ...budget, expenses: budget.expenses.filter((expense) => expense.id !== id) });
  };
  const expenses = mode === "actual" ? operation.actualExpenses ?? [] : budget?.expenses ?? [];
  return <section className="panel financial-workspace"><div className="financial-workspace__heading"><div><h2>{approved ? "Custos aprovados e realizados" : "Estimativa de custos"}</h2><p>{approved ? "Compare os custos aprovados com as despesas registradas na operação." : "Lance os produtos, tributos e despesas para preparar os custos da importação."}</p></div>{approved && <label className="field"><span>Visão financeira</span><FieldSelect label="Visão financeira" value={mode} onValueChange={(value) => setMode(value as "budget" | "actual")}><SelectOption value="budget">Custos aprovados</SelectOption><SelectOption value="actual">Despesas realizadas</SelectOption></FieldSelect></label>}</div>
    {mode === "budget" && !budget && <div className="financial-empty"><div><strong>Organize os custos da importação</strong><p>Converta os valores já lançados em uma versão rastreável, pronta para aprovação.</p></div><button className="button button--primary" onClick={ensureBudget}>Estruturar custos</button></div>}
    {mode === "budget" && budget && <><div className="budget-toolbar"><div><span className={`status status--${budget.status === "approved" ? "success" : "info"}`}>{budget.status === "approved" ? "Aprovado" : "Em preparação"}</span><strong>{budget.name}</strong><small>Versão {budget.number}</small></div></div><div className="budget-methods" data-localized><label className="field"><span>Modelo de cálculo</span><FieldSelect label="Modelo de cálculo" disabled={approved} value={budget.calculationModel ?? "legacy"} onValueChange={(value) => saveBudget({ ...budget, calculationModel: value as ImportBudget["calculationModel"] }, { title: "Modelo de cálculo alterado", description: value === "worksheet" ? "Modelo da planilha selecionado; revise bases, pesos e alíquotas." : "Modelo anterior selecionado.", type: "milestone" })}><SelectOption value="legacy">Modelo anterior</SelectOption><SelectOption value="worksheet">Modelo da planilha</SelectOption></FieldSelect></label>{budget.calculationModel === "worksheet" && <><label className="field"><span>Base dos produtos</span><FieldSelect label="Base dos produtos" disabled={approved} value={budget.priceBasis ?? "fob"} onValueChange={(value) => saveBudget({ ...budget, priceBasis: value as ImportBudget["priceBasis"] })}><SelectOption value="fob">FOB · frete e seguro separados</SelectOption><SelectOption value="cif">CIF · frete e seguro incluídos</SelectOption></FieldSelect></label><label className="field"><span>Regra de venda</span><FieldSelect label="Regra de venda" disabled={approved} value={budget.marginMethod ?? "markup"} onValueChange={(value) => saveBudget({ ...budget, marginMethod: value as ImportBudget["marginMethod"] })}><SelectOption value="markup">Acréscimo sobre custo</SelectOption><SelectOption value="sale_margin">Margem sobre venda</SelectOption></FieldSelect></label></>}</div>{calculated.calculationWarnings.length > 0 && <ul className="calculation-alerts" data-localized>{calculated.calculationWarnings.map(warning => <li key={warning}>{translateUiText(activeLocale, warning)}</li>)}</ul>}{budget.calculationModel === "worksheet" && <p className="item-pricing-note" data-localized>{translateUiText(activeLocale, "Modelo operacional da empresa. ICMS de entrada não calculado; Siscomex e AFRMM são despesas em reais. Revise o enquadramento tributário com o contador.")}</p>}<div className="cost-inputs budget-assumptions"><NumberField label="Câmbio (R$/US$)" value={budget.exchangeRate} step="0.01" onChange={(value) => saveBudget({ ...budget, exchangeRate: value })} /><NumberField label={budget.calculationModel === "worksheet" && budget.marginMethod !== "sale_margin" ? "Acréscimo sobre custo (%)" : "Margem sobre venda (%)"} value={budget.marginRate} step="0.01" onChange={(value) => saveBudget({ ...budget, marginRate: value })} /></div><div className="budget-readouts"><div className="financial-readout"><span>{budget.priceBasis === "cif" && budget.calculationModel === "worksheet" ? "CIF dos produtos" : "FOB estimado"}</span><MoneyValue value={calculated.fobBrl} /></div><div className="financial-readout"><span>Tributos de entrada</span><MoneyValue value={calculated.taxes} /></div><div className="financial-readout" data-localized><span>{translateUiText(activeLocale, "Preço sugerido de venda")}</span>{calculated.suggestedSaleTotal !== null ? <MoneyValue value={calculated.suggestedSaleTotal} /> : <small role="alert">{translateUiText(activeLocale, "Revise a margem e as bases de rateio.")}</small>}<small>{translateUiText(activeLocale, "Considera a margem desejada.")}</small></div></div></>}
    {mode === "actual" && <><div className="budget-toolbar"><div><span className="status status--warning">{shipmentStatusMeta[operation.shipmentStatus ?? "not_shipped"].label}</span><strong>Custos realizados</strong><small>Informe valores contratados, faturados e pagos para comparar com o orçamento.</small></div><Select value={operation.shipmentStatus ?? "not_shipped"} onValueChange={(value) => onUpdate(operation.id, { shipmentStatus: value as ShipmentStatus })}><SelectTrigger className="financial-select" aria-label="Status do embarque"><SelectValue /></SelectTrigger><SelectContent>{Object.entries(shipmentStatusMeta).map(([value, meta]) => <SelectItem value={value} key={value}>{meta.label}</SelectItem>)}</SelectContent></Select></div><div className="financial-variance"><span>Realizado <MoneyValue value={actualTotal} /></span><span>Orçado <MoneyValue value={calculated.baseExpenses} /></span><span className={actualTotal > calculated.baseExpenses ? "is-negative" : "is-positive"}>Variação <MoneyValue value={actualTotal - calculated.baseExpenses} /></span></div></>}
    {(mode === "actual" || budget) && <>{mode === "budget" && <div className="budget-expenses-heading" data-localized><h3>{translateUiText(activeLocale, "Despesas estimadas")}</h3><div><span>{translateUiText(activeLocale, "Subtotal das despesas")}</span><MoneyValue value={calculated.baseExpenses} /></div></div>}<div className="expense-list"><div className="expense-list__header"><span>Despesa / tipo</span><span>Rateio</span><span>Status</span><span>Valor</span><span><span className="sr-only">Ações</span></span></div>{expenses.length === 0 ? <div className="expense-list__empty">Nenhuma despesa lançada nesta visão.</div> : expenses.map((expense) => <ExpenseRow key={expense.id} worksheet={budget?.calculationModel === "worksheet" && mode === "budget"} expense={expense} onChange={(changes) => updateExpense(expense.id, changes, mode === "actual")} onRemove={() => removeExpense(expense.id, mode === "actual")} />)}<button className="button button--secondary expense-list__add" onClick={() => addExpense(mode === "actual")}><Plus size={16} /> {mode === "actual" ? "Adicionar custo realizado" : "Adicionar despesa estimada"}</button></div></>}
    <div className="cost-result">{mode === "actual" ? <div className="cost-breakdown"><span>Base dos produtos <MoneyValue value={calculated.fobBrl} /></span><span>Custos rateados <MoneyValue value={calculated.baseExpenses} /></span><span>Tributos <MoneyValue value={calculated.taxes} /></span></div> : <p className="budget-total-explanation" data-localized>{translateUiText(activeLocale, "Base dos produtos + despesas + tributos de entrada. Não inclui acréscimo de venda nem tributos de saída.")}</p>}<div className="cost-total"><span>{mode === "actual" ? "Realizado" : "Custo total projetado"}</span><MoneyValue value={mode === "actual" ? actualTotal : calculated.totalCost} /><small>{mode === "actual" ? "despesas registradas" : "estimativa do orçamento"}</small></div></div>
  </section>;
}
function ExpenseRow({ expense, worksheet, onChange, onRemove }: { worksheet?: boolean; expense: ImportExpense; onChange: (changes: Partial<ImportExpense>) => void; onRemove: () => void }) { return <div className="expense-row"><div className="expense-description"><Input autoComplete="off" value={expense.label} onChange={(event) => onChange({ label: event.target.value })} aria-label="Descrição da despesa" />{worksheet && <FieldSelect label="Tipo de despesa" value={expense.kind ?? "other"} onValueChange={(value) => onChange({ kind: value as ImportExpense["kind"], ...(["siscomex", "afrmm"].includes(value) ? { allocationMethod: "weight" as const } : {}) })}><SelectOption value="other">Outras despesas</SelectOption><SelectOption value="freight">Frete internacional</SelectOption><SelectOption value="insurance">Seguro internacional</SelectOption><SelectOption value="siscomex">Taxa Siscomex</SelectOption><SelectOption value="afrmm">AFRMM</SelectOption></FieldSelect>}</div><Select disabled={worksheet && ["siscomex", "afrmm"].includes(expense.kind ?? "")} value={expense.allocationMethod} onValueChange={(value) => onChange({ allocationMethod: value as ExpenseAllocationMethod })}><SelectTrigger aria-label="Método de rateio"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="fob">Por valor dos produtos</SelectItem><SelectItem value="weight">Por peso</SelectItem><SelectItem value="volume">Por volume</SelectItem><SelectItem value="quantity">Por quantidade</SelectItem><SelectItem value="fixed">Igual por item</SelectItem></SelectContent></Select><Select value={expense.status} onValueChange={(value) => onChange({ status: value as ExpenseStatus })}><SelectTrigger aria-label="Status da despesa"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="estimated">Estimado</SelectItem><SelectItem value="approved">Aprovado</SelectItem><SelectItem value="contracted">Contratado</SelectItem><SelectItem value="invoiced">Faturado</SelectItem><SelectItem value="paid">Pago</SelectItem></SelectContent></Select><NumberInput currency={expense.currency} value={expense.amount} onValueChange={(amount) => onChange({ amount })} aria-label="Valor da despesa" /><button type="button" className="table-action table-action--danger" onClick={onRemove} aria-label={`Remover ${expense.label}`}><Trash2 size={16} /></button></div>; }
function TaxSettingsView({ token }: { token: string }) {
  const [rates, setRates] = useState<TaxRate[]>(configuredTaxRates); const [saving, setSaving] = useState(false); const [saved, setSaved] = useState(false); const [loading, setLoading] = useState(true); const [message, setMessage] = useState("");
  useEffect(() => { let active = true; apiFetch(`${apiUrl}/api/settings/tax-rates`, { headers: { authorization: `Bearer ${token}` } }).then(async (response) => response.ok ? response.json() as Promise<{ value: TaxRate[] }> : Promise.reject(new Error(response.status === 404 || response.status === 401 ? "" : "Não foi possível carregar as parametrizações."))).then((payload) => { if (active && Array.isArray(payload.value)) { setRates(payload.value); localStorage.setItem(taxSettingsStorageKey, JSON.stringify(payload.value)); } }).catch((error: unknown) => { if (active && error instanceof Error && error.message) setMessage(error.message); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [token]);
  const entry = rates.filter((rate) => ["ii", "ipi", "pis_import", "cofins_import", "icms_import", "siscomex", "afrmm"].includes(rate.code)); const exit = rates.filter((rate) => !entry.includes(rate));
  const updateRate = (code: TaxRateCode, rate: number) => { if (saving) return; setRates((current) => current.map((item) => item.code === code ? { ...item, rate, source: "manual", updatedAt: new Date().toISOString() } : item)); setSaved(false); };
  const save = async () => { if (saving) return; setSaving(true); setMessage(""); try { const response = await apiFetch(`${apiUrl}/api/settings/tax-rates`, { method: "PUT", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify({ value: rates }) }); const payload = await response.json() as { value?: TaxRate[]; message?: string }; if (!response.ok) throw new Error(payload.message || "Não foi possível salvar as parametrizações."); const persisted = payload.value ?? rates; setRates(persisted); localStorage.setItem(taxSettingsStorageKey, JSON.stringify(persisted)); setSaved(true); } catch (error) { setMessage(error instanceof Error ? error.message : "Não foi possível salvar as parametrizações."); } finally { setSaving(false); } };
  const block = (title: string, items: TaxRate[]) => <section className="panel tax-settings__section"><div className="panel-header"><div><h2>{title}</h2><p>Valores padrão para novas versões de orçamento. A alíquota pode ser ajustada por NCM ou dentro da operação.</p></div></div><div className="tax-settings__rates">{items.map((item) => <NumberField key={item.code} label={taxRateLabels[item.code]} value={item.rate} step="0.01" prefix="%" disabled={saving} onChange={(value) => updateRate(item.code, value)} />)}</div></section>;
  if (loading) return <section className="page tax-settings" aria-busy="true"><div className="page-heading"><div><Skeleton className="skeleton--headline" /><Skeleton className="skeleton--line" /></div></div><section className="panel tax-settings__section"><Skeleton className="skeleton--line" /><div className="tax-settings__rates">{Array.from({ length: 8 }, (_, index) => <Skeleton key={index} className="skeleton--input" />)}</div></section></section>;
  return <section className="page tax-settings"><div className="page-heading"><div><h1>Parametrizações</h1><p className="muted">Defina as premissas usadas para iniciar novos orçamentos de importação.</p></div><button disabled={saving} className="button button--primary" onClick={() => void save()}><Check size={17} /> {saving ? "Salvando…" : saved ? "Parâmetros salvos" : "Salvar parâmetros"}</button></div>{message && <p className="users-message" role="alert">{message}</p>}<div className="tax-settings__notice"><FileText size={18} aria-hidden="true" /><p>As alíquotas são premissas operacionais. Quando a integração do Siscomex estiver credenciada, o sistema registrará a origem e a data da consulta antes da aprovação.</p></div>{block("Impostos de entrada", entry)}{block("Impostos de saída", exit)}</section>;
}

function MoneyValue({ value }: { value: number }) { return <strong><MoneyAmount value={value} /></strong>; }
function NumberField({ label, value, onChange, prefix, step = "1", disabled = false }: { label: string; value: number; onChange: (value: number) => void; prefix?: string; step?: string; disabled?: boolean }) { return <label className="field"><span>{label}</span><NumberInput value={value} onValueChange={onChange} disabled={disabled} decimalScale={label.includes("R$/US$") ? 4 : step === "1" ? 0 : 2} suffix={prefix === "%" || label.includes("(%)") ? "%" : undefined} prefix={prefix !== "%" ? prefix : undefined} /></label>; }
function Summary({ label, value, detail, emphasis, monetaryValue }: { label: string; value: string; detail: string; emphasis?: "primary"; monetaryValue?: number }) { return <div className={`summary-card${emphasis ? ` summary-card--${emphasis}` : ""}`}><span>{label}</span><strong data-localized key={value}>{value}</strong>{monetaryValue !== undefined && <CurrencyEquivalents value={monetaryValue} />}<small>{detail}</small></div>; }
function Metric({ icon, label, value, detail, tone, monetaryValue }: { icon: ReactNode; label: string; value: string; detail: ReactNode; tone: string; monetaryValue?: number }) { return <section className={`metric-card tone-${tone}`}><span className="metric-icon">{icon}</span><p>{label}</p><strong data-localized>{value}</strong>{monetaryValue !== undefined && <CurrencyEquivalents value={monetaryValue} />}<div className="metric-detail">{detail}</div></section>; }
function StatusBadge({ status }: { status: ImportStatus }) { const meta = importStatusMeta[status]; return <span className={`status status--${meta.tone}`}>{meta.label}</span>; }
function Dialog({ title, onClose, children, className }: { title: string; onClose: () => void; children: ReactNode; className?: string }) { const locale = useLocale(); return <DialogRoot open onOpenChange={(open) => { if (!open) onClose(); }}><DialogContent className={className} aria-describedby={undefined}><header><DialogTitle asChild><h2 data-localized>{translateUiText(locale, title)}</h2></DialogTitle><DialogClose asChild><button className="icon-button" aria-label="Fechar"><X size={20} /></button></DialogClose></header>{children}</DialogContent></DialogRoot>; }
function ProductSheetPicker({ token, onProductsChange, onReadingChange, onBudgetChange }: { token: string; onProductsChange: (items: ImportedProduct[]) => void; onBudgetChange?: (budget?: SheetBudget) => void; onReadingChange: (reading: boolean) => void }) {
  const locale = useLocale();
  const [fileName, setFileName] = useState("");
  const [sheetBudget, setSheetBudget] = useState<SheetBudget | undefined>();
  const [budgetMode, setBudgetMode] = useState("products");
  const [items, setItems] = useState<ImportedProduct[]>([]);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [error, setError] = useState("");
  const [reading, setReading] = useState(false);
  const [translationProgress, setTranslationProgress] = useState<{ done: number; total: number } | null>(null);
  const readFile = async (file?: File) => {
    if (!file || reading) return;
    setSheetBudget(undefined); setBudgetMode("products"); onBudgetChange?.(undefined); setTranslationProgress(null); setReading(true); onReadingChange(true); setError(""); setWarnings([]); setItems([]); setFileName(""); onProductsChange([]);
    try {
      const result = await parseProductSheet(file);
      result.items = await translateImportedProducts(result.items, apiUrl, token, (done, total) => { if (total) setTranslationProgress({ done, total }); });
      setSheetBudget(result.budget); setItems(result.items); setFileName(file.name); setWarnings(result.warnings); onProductsChange(result.items);
    } catch (reason) {
      setItems([]); setFileName(""); onProductsChange([]);
      setError(reason instanceof Error ? reason.message : "Não foi possível ler a planilha.");
    } finally { setReading(false); onReadingChange(false); }
  };
  return <section className="product-sheet-importer" aria-busy={reading}>
    <div className="product-sheet-importer__intro"><div><strong>Produtos por planilha</strong><p>Envie XLSX, XLS ou CSV. As colunas Produto e Quantidade são obrigatórias; NCM, valores em USD, peso, II e IPI são opcionais.</p></div><label className="button button--secondary" aria-disabled={reading} htmlFor="product-sheet-input">{reading ? <Spinner /> : <Upload size={17} />} <span data-localized>{translateUiText(locale, reading ? (translationProgress ? "Traduzindo produtos…" : "Lendo planilha…") : "Selecionar planilha")}</span><input autoComplete="off" id="product-sheet-input" className="sr-only" type="file" disabled={reading} accept=".xlsx,.xls,.csv" onChange={(event) => { void readFile(event.target.files?.[0]); event.currentTarget.value = ""; }} /></label></div>
    {reading && <div className="product-sheet-importer__loading"><div className="product-sheet-importer__loading-status" role="status" aria-live="polite"><Spinner /><div><strong data-localized>{translateUiText(locale, translationProgress ? "Traduzindo produtos…" : "Lendo planilha…")}</strong><p>{translationProgress ? `${translationProgress.done} / ${translationProgress.total}` : "Extraindo os produtos e valores. Aguarde para continuar."}</p></div></div><div className="table-scroll" aria-hidden="true"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>NCM</th><th>USD unit.</th></tr></thead><tbody><TableSkeletonRows columns={4} rows={3} /></tbody></table></div></div>}
    {error && <p className="product-sheet-importer__error" role="alert">{error}</p>}
    {warnings.length > 0 && <ul className="product-sheet-importer__warning" role="status">{warnings.map((warning, index) => <li key={index}>{translateUiText(locale, warning)}</li>)}</ul>}{sheetBudget && onBudgetChange && <label className="field" data-localized><span>{translateUiText(locale, "Premissas da planilha")}</span><FieldSelect label={translateUiText(locale, "Premissas da planilha")} value={budgetMode} onValueChange={(value) => { setBudgetMode(value); onBudgetChange(value === "budget" ? sheetBudget : undefined); }}><SelectOption value="products">{translateUiText(locale, "Importar somente produtos")}</SelectOption><SelectOption value="budget">{translateUiText(locale, "Aplicar câmbio, margem e despesas da planilha")}</SelectOption></FieldSelect><small>{translateUiText(locale, "As premissas só podem ser aplicadas a um orçamento vazio e não aprovado.")}</small></label>}
    {items.some((item) => !item.name.trim()) && <p className="product-sheet-importer__warning" role="status" data-localized>{`${items.filter((item) => !item.name.trim()).length} · ${translateUiText(locale, "Preencha o nome em português nos detalhes da importação.")}`}</p>}
    {items.length > 0 && <div className="product-sheet-importer__preview"><div><strong>{fileName}</strong><span>{items.length} produto(s) encontrados</span></div><div className="table-scroll"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>NCM</th><th>USD unit.</th></tr></thead><tbody>{items.slice(0, 5).map((item, index) => <tr key={`${item.name}-${index}`}><td><strong>{item.name || translateUiText(activeLocale, "Nome em português pendente")}</strong>{item.chineseName && <small lang="zh">{item.chineseName}</small>}</td><td>{item.quantity}</td><td>{item.ncm || "—"}</td><td>{<MoneyAmount value={item.unitPriceUsd} currency="USD" />}</td></tr>)}</tbody></table></div>{items.length > 5 && <small>Mostrando os primeiros 5 itens da planilha.</small>}</div>}
  </section>;
}
function ProductSheetImportDialogContent({ token, onConfirm, allowBudget }: { allowBudget: boolean; token: string; onConfirm: (items: ImportedProduct[], budget?: SheetBudget) => void }) {
  const [items, setItems] = useState<ImportedProduct[]>([]);
  const [sheetBudget, setSheetBudget] = useState<SheetBudget | undefined>();
  const [reading, setReading] = useState(false);
  return <div className="product-sheet-dialog" aria-busy={reading}><ProductSheetPicker token={token} onBudgetChange={allowBudget ? setSheetBudget : undefined} onProductsChange={setItems} onReadingChange={setReading} /><div className="product-sheet-dialog__actions"><Button className="button button--primary" type="button" disabled={reading || !items.length} onClick={() => { if (!reading) onConfirm(items, sheetBudget); }}><Upload size={17} /><span>{`Incluir ${items.length} ${items.length === 1 ? "produto" : "produtos"}`}</span></Button></div></div>;
}
function ImportForm({ token, creating, error, customers, customerId, port, onSelectPort, onSelectCustomer, onNewCustomer, onSubmit }: { token: string; creating: boolean; error: string; customers: Customer[]; customerId: string; port: string; onSelectPort: () => void; onSelectCustomer: () => void; onNewCustomer: () => void; onSubmit: (event: FormEvent<HTMLFormElement>, importedItems: ImportedProduct[], sheetBudget?: SheetBudget) => void }) {
  const customer = customers.find((item) => item.id === customerId);
  const [importedItems, setImportedItems] = useState<ImportedProduct[]>([]);
  const [sheetBudget, setSheetBudget] = useState<SheetBudget | undefined>();
  const [reading, setReading] = useState(false);
  const busy = reading || creating;
  return <form autoComplete="off" className="import-form-container" aria-busy={busy} onSubmit={(event) => { if (busy) { event.preventDefault(); return; } onSubmit(event, importedItems, sheetBudget); }}>
    <fieldset className="form-grid import-form" disabled={busy} aria-label="Dados da importação">
    <div className="field full">
      <span id="import-customer-label">Cliente</span>
      <input autoComplete="off" name="customerId" value={customerId} type="hidden" readOnly />
      <div className="customer-picker">
        <Button className="customer-picker__trigger" aria-labelledby="import-customer-label" onClick={onSelectCustomer}><span>{customer ? customer.tradeName || customer.legalName : "Selecionar cliente"}</span><ChevronRight size={17} /></Button>
        <Button className="button button--secondary import-form__new-customer" onClick={onNewCustomer}><Plus size={15} /> Novo cliente</Button>
      </div>
    </div>
    <label className="field"><span data-localized>ETA</span><DatePicker name="eta" label="ETA" required /></label>
    <div className="field">
      <span id="import-port-label">Porto de destino</span>
      <input autoComplete="off" type="hidden" name="port" value={port} readOnly />
      <Button className="customer-picker__trigger" aria-labelledby="import-port-label" aria-describedby="import-port-help" onClick={onSelectPort}><span data-localized>{port || translateUiText(activeLocale, "Porto a definir")}</span><ChevronRight size={17} /></Button>
      <small id="import-port-help" className="muted">Pode ser definido depois nos detalhes da importação.</small>
    </div>
    <div className="full"><ProductSheetPicker token={token} onBudgetChange={setSheetBudget} onProductsChange={setImportedItems} onReadingChange={setReading} /></div>
    {error && <p className="field-error full" role="alert">{error}</p>}
    <Button className="button button--primary form-submit" type="submit" disabled={busy}>{busy ? <Spinner /> : <Plus size={18} />}<span data-localized>{translateUiText(activeLocale, creating ? "Criando importação…" : reading ? "Lendo planilha…" : "Criar importação")}</span></Button>
    </fieldset>
  </form>;
}

function PortPickerContent({ facilities, state, error, onRetry, onBack, onSelect }: { facilities: PortFacility[]; state: "idle" | "loading" | "ready" | "error"; error: string; onRetry: () => void; onBack: () => void; onSelect: (port: string) => void }) {
  const [query, setQuery] = useState("");
  const normalize = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const visible = facilities.filter((port) => normalize(`${port.name} ${port.municipality} ${port.state}`).includes(normalize(query.trim())));
  return <div className="customer-picker-dialog"><div className="customer-picker-dialog__toolbar"><Button className="text-button" onClick={onBack}><ArrowLeft size={16} /> Voltar</Button><label className="search-field"><Search size={17} /><Input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por porto, cidade ou estado" aria-label="Buscar portos" /></label></div><div className="customer-picker-dialog__list"><Button onClick={() => onSelect("")}><span><strong>Ainda não sei o porto</strong><small>Definir depois nos detalhes da importação</small></span><ChevronRight size={18} /></Button>{state === "idle" || state === "loading" ? <div aria-busy="true"><Skeleton className="skeleton--input" /><Skeleton className="skeleton--input" /><Skeleton className="skeleton--input" /></div> : state === "error" ? <div role="alert"><p>{error}</p><Button className="text-button" onClick={onRetry}>Tentar novamente</Button></div> : visible.length === 0 ? <p className="customer-picker-dialog__empty">Nenhum porto corresponde à busca.</p> : visible.map((port) => <Button key={port.id} onClick={() => onSelect(port.name)}><span><strong>{port.name}</strong><small>{port.municipality}/{port.state}</small></span><ChevronRight size={18} /></Button>)}</div></div>;
}
function CustomerPickerContent({ customers, onBack, onSelect, onNewCustomer }: { customers: Customer[]; onBack: () => void; onSelect: (id: string) => void; onNewCustomer: () => void }) { const [query, setQuery] = useState(""); const visible = customers.filter((customer) => customer.status === "active" && `${customer.legalName} ${customer.tradeName} ${customer.taxId}`.toLowerCase().includes(query.toLowerCase())); return <div className="customer-picker-dialog"><div className="customer-picker-dialog__toolbar"><button className="text-button" type="button" onClick={onBack}><ArrowLeft size={16} /> Voltar</button><label className="search-field"><Search size={17} /><input autoComplete="off" autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por empresa ou CNPJ" aria-label="Buscar clientes" /></label><button className="text-button" type="button" onClick={onNewCustomer}><Plus size={16} /> Novo cliente</button></div><div className="customer-picker-dialog__list">{visible.length === 0 ? <p className="customer-picker-dialog__empty">Nenhum cliente ativo corresponde à busca.</p> : visible.map((customer) => <button type="button" key={customer.id} onClick={() => onSelect(customer.id)}><span><strong>{customer.tradeName || customer.legalName}</strong><small>{customer.legalName} · {customer.taxId}</small></span><ChevronRight size={18} /></button>)}</div></div>; }
function UserAvatar({ user, large = false }: { user: Pick<SessionUser, "name" | "avatarUrl">; large?: boolean }) { const initials = user.name.split(" ").filter(Boolean).map((part) => part[0]).slice(0, 2).join("").toUpperCase(); return user.avatarUrl ? <img className={`user-avatar${large ? " user-avatar--large" : ""}`} src={user.avatarUrl} alt="" /> : <span className={`avatar${large ? " avatar--large" : ""}`}>{initials}</span>; }
function UsersManagementView({ token, onSessionExpired, onUserUpdated }: { token: string; onSessionExpired: () => void; onUserUpdated: (user: SessionUser) => void }) { const [editingUser, setEditingUser] = useState<SessionUser | null>(null); const [users, setUsers] = useState<SessionUser[]>([]); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(""); const load = async () => { setLoading(true); try { const response = await apiFetch(`${apiUrl}/api/users`, { headers: { authorization: `Bearer ${token}` } }); if (response.status === 401) return onSessionExpired(); const data = await response.json() as SessionUser[] | { message?: string }; if (Array.isArray(data)) setUsers(data); else setMessage(data.message || "Não foi possível carregar usuários."); } catch { setMessage("Não foi possível carregar usuários."); } finally { setLoading(false); } }; useEffect(() => { void load(); }, []); const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setMessage(""); const formElement = event.currentTarget; const form = new FormData(formElement); const response = await apiFetch(`${apiUrl}/api/users`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify({ name: form.get("name"), email: form.get("email"), role: form.get("role"), initialPassword: form.get("initialPassword") }) }); const payload = await response.json() as SessionUser | { message?: string }; if (!response.ok || !("id" in payload)) return setMessage("message" in payload ? payload.message || "Não foi possível cadastrar o usuário." : "Não foi possível cadastrar o usuário."); setUsers((current) => [...current, payload]); onUserUpdated(payload); formElement.reset(); setMessage("Usuário cadastrado. A troca de senha será exigida no primeiro acesso."); }; return <section className="page users-page"><div className="page-heading"><div><p className="eyebrow">ADMINISTRAÇÃO DE ACESSOS</p><h1>Usuários</h1><p className="muted">Crie acessos e acompanhe quem trabalha nas operações.</p></div></div><div className="users-layout"><section className="panel users-list-panel"><div className="panel-header"><div><h2>Usuários cadastrados</h2><p>{loading ? "Carregando acessos…" : `${users.length} acesso${users.length === 1 ? "" : "s"} no sistema.`}</p></div></div>{message && <p className="users-message" role="status">{message}</p>}<div className="table-scroll"><table className="users-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Contato</th><th>Cadastro</th><th>Acesso</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{loading ? <TableSkeletonRows columns={6} rows={5} /> : users.map((user) => <tr key={user.id}><td><span className="user-cell"><UserAvatar user={user} /><span><strong>{user.name}</strong><small>{user.jobTitle || "Dados profissionais pendentes"}</small></span></span></td><td><span className={`status status--${user.role === "admin" ? "info" : "neutral"}`}>{user.role === "admin" ? "Administrador" : "Operador"}</span></td><td><strong>{user.email}</strong><small>{user.phone || "Telefone não informado"}</small></td><td>{formatDate(user.createdAt.slice(0, 10))}</td><td><span className={`status status--${user.mustChangePassword ? "warning" : "success"}`}>{user.mustChangePassword ? "Primeiro acesso" : "Ativo"}</span></td><td><Button className="table-action" aria-label={`Editar usuário ${user.name}`} onClick={() => setEditingUser(user)}><Pencil size={16} /></Button></td></tr>)}</tbody></table></div></section><section className="panel user-create-panel"><div className="panel-header"><div><h2>Novo usuário</h2><p>A pessoa conclui o próprio perfil no primeiro acesso.</p></div></div><form autoComplete="off" className="form-grid" onSubmit={create}><label className="field full"><span>Nome completo</span><input autoComplete="off" name="name" required placeholder="Nome da pessoa" /></label><label className="field full"><span>E-mail corporativo</span><input autoComplete="off" name="email" type="email" required placeholder="nome@empresa.com.br" /></label><label className="field"><span>Perfil</span><FieldSelect label="Perfil" name="role" defaultValue="operator"><SelectOption value="operator">Operador</SelectOption><SelectOption value="admin">Administrador</SelectOption></FieldSelect></label><label className="field"><span>Senha inicial</span><input autoComplete="off" name="initialPassword" type="password" minLength={8} required placeholder="Mínimo de 8 caracteres" /></label><button className="button button--primary form-submit"><UserPlus size={18} /> Cadastrar usuário</button></form></section></div>{editingUser && <UserEditDialog user={editingUser} token={token} onClose={() => setEditingUser(null)} onSaved={(user) => { setUsers((current) => current.map((item) => item.id === user.id ? user : item)); onUserUpdated(user); setMessage("Usuário atualizado."); setEditingUser(null); }} />}</section>; }
function UserEditDialog({ user, token, onClose, onSaved }: { user: SessionUser; token: string; onClose: () => void; onSaved: (user: SessionUser) => void }) {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (saving) return;
    const form = new FormData(event.currentTarget);
    setSaving(true); setError("");
    try {
      const response = await apiFetch(`${apiUrl}/api/users/${user.id}`, { method: "PATCH", headers: { "content-type": "application/json", authorization: `Bearer ${token}` }, body: JSON.stringify(Object.fromEntries(["name", "email", "role", "phone", "jobTitle"].map((key) => [key, form.get(key)]))) });
      const payload = await response.json() as SessionUser | { message?: string };
      if (!response.ok || !("id" in payload)) throw new Error("message" in payload ? payload.message || "Não foi possível atualizar o usuário." : "Não foi possível atualizar o usuário.");
      onSaved(payload);
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível atualizar o usuário."); }
    finally { setSaving(false); }
  };
  return <Dialog title="Editar usuário" onClose={() => { if (!saving) onClose(); }}><form autoComplete="off" className="form-grid" onSubmit={submit} aria-busy={saving}>
    <fieldset className="form-grid full" disabled={saving} style={{ border: 0, padding: 0, margin: 0 }}>
      <label className="field full"><span>Nome completo</span><Input name="name" required maxLength={200} defaultValue={user.name} autoFocus /></label>
      <label className="field full"><span>E-mail corporativo</span><Input name="email" type="email" required maxLength={254} defaultValue={user.email} /></label>
      <label className="field full"><span>Perfil</span><FieldSelect name="role" label="Perfil de acesso" defaultValue={user.role} disabled={saving}><SelectOption value="operator">Operador</SelectOption><SelectOption value="admin">Administrador</SelectOption></FieldSelect></label>
      <label className="field"><span>Telefone</span><Input name="phone" type="tel" maxLength={50} defaultValue={user.phone} /></label>
      <label className="field"><span>Cargo ou área</span><Input name="jobTitle" maxLength={200} defaultValue={user.jobTitle} /></label>
    </fieldset>
    {error && <p className="field-error full" role="alert">{error}</p>}
    <div className="full" style={{ display: "flex", justifyContent: "flex-end", gap: 12 }}><Button className="button button--secondary" disabled={saving} onClick={onClose}>Cancelar</Button><Button className="button button--primary" type="submit" disabled={saving}>{saving ? <Spinner /> : <Check size={17} />}{saving ? "Salvando…" : "Salvar alterações"}</Button></div>
  </form></Dialog>;
}
function AvatarEditorDialog({ file, saving, onClose, onSave }: { file: File; saving: boolean; onClose: () => void; onSave: (file: File) => Promise<boolean> }) {
  const [crop, setCrop] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [area, setArea] = useState<Area | null>(null);
  const [error, setError] = useState("");
  const [preparing, setPreparing] = useState(false);
  const [source, setSource] = useState("");
  useEffect(() => { const objectUrl = URL.createObjectURL(file); setSource(objectUrl); return () => URL.revokeObjectURL(objectUrl); }, [file]);
  const adjustZoom = (amount: number) => setZoom((current) => Math.min(3, Math.max(1, current + amount)));
  const adjustRotation = (amount: number) => setRotation((current) => (current + amount + 360) % 360);
  const confirm = async () => {
    if (!area) return setError("Aguarde a imagem ser preparada.");
    setPreparing(true); setError("");
    try {
      const cropped = await cropAvatar(source, area, rotation);
      if (cropped.size > 1024 * 1024) return setError("A imagem ajustada excede 1 MB. Reduza o zoom ou escolha outra foto.");
      if (await onSave(cropped)) onClose();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível ajustar a imagem."); }
    finally { setPreparing(false); }
  };
  const busy = saving || preparing;
  return <Dialog title="Ajustar foto de perfil" onClose={onClose} className="avatar-editor-dialog"><div className="avatar-editor"><div className="avatar-editor__stage">{source && <Cropper image={source} crop={crop} zoom={zoom} rotation={rotation} aspect={1} cropShape="round" showGrid={false} disableAutomaticStylesInjection onCropChange={setCrop} onZoomChange={setZoom} onCropComplete={(_, pixels) => setArea(pixels)} />}</div><p className="avatar-editor__hint">Arraste a imagem para posicioná-la dentro do recorte circular.</p><div className="avatar-editor__controls"><div className="avatar-editor__control"><span><ZoomOut size={16} aria-hidden="true" /> Zoom</span><button type="button" className="avatar-editor__step" onClick={() => adjustZoom(-0.1)} disabled={zoom <= 1 || busy} aria-label="Reduzir zoom"><ZoomOut size={16} /></button><Slider min={1} max={3} step={0.01} value={[zoom]} onValueChange={([value]) => setZoom(value)} disabled={busy} aria-label="Zoom da foto" /><button type="button" className="avatar-editor__step" onClick={() => adjustZoom(0.1)} disabled={zoom >= 3 || busy} aria-label="Aumentar zoom"><ZoomIn size={16} /></button></div><div className="avatar-editor__control"><span><RotateCcw size={16} aria-hidden="true" /> Rotação</span><button type="button" className="avatar-editor__step" onClick={() => adjustRotation(-90)} disabled={busy} aria-label="Girar 90 graus para a esquerda"><RotateCcw size={16} /></button><Slider min={0} max={359} step={1} value={[rotation]} onValueChange={([value]) => setRotation(value)} disabled={busy} aria-label="Rotação da foto" /><button type="button" className="avatar-editor__reset" onClick={() => { setCrop({ x: 0, y: 0 }); setZoom(1); setRotation(0); }} disabled={busy}>Redefinir</button></div></div>{error && <p className="avatar-editor__error" role="alert">{error}</p>}<div className="avatar-editor__actions"><button type="button" className="button button--secondary" onClick={onClose} disabled={busy}>Cancelar</button><button type="button" className="button button--primary" onClick={confirm} disabled={busy || !source}>{busy ? "Salvando…" : "Usar esta foto"}</button></div></div></Dialog>;
}

function MyProfileView({ session, onSessionUpdate }: { session: { token: string; user: SessionUser }; onSessionUpdate: (next: { token: string; user: SessionUser }) => void }) {
  const [profile, setProfile] = useState(session.user);
  const [message, setMessage] = useState("");
  const [saving, setSaving] = useState(false);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  useEffect(() => { apiFetch(`${apiUrl}/api/me`, { headers: { authorization: `Bearer ${session.token}` } }).then((response) => response.ok ? response.json() : null).then((data: SessionUser | null) => { if (data) setProfile(data); }).catch(() => undefined); }, [session.token]);
  const selectImage = (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 10 * 1024 * 1024) return setMessage("Escolha uma imagem JPG, PNG ou WebP de até 10 MB."); setMessage(""); setAvatarFile(file); };
  const uploadAvatar = async (file: File) => { setSaving(true); setMessage(""); try { const body = new FormData(); body.set("file", file); const response = await apiFetch(`${apiUrl}/api/me/avatar`, { method: "POST", headers: { authorization: `Bearer ${session.token}` }, body }); const data = await response.json() as SessionUser | { message?: string }; if (!response.ok || !("id" in data)) throw new Error("message" in data ? data.message || "Não foi possível enviar a imagem." : "Não foi possível enviar a imagem."); setProfile(data); onSessionUpdate({ token: session.token, user: data }); setMessage("Imagem atualizada."); return true; } catch (error) { setMessage(error instanceof Error ? error.message : "Não foi possível enviar a imagem."); return false; } finally { setSaving(false); } };
  const save = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSaving(true); setMessage(""); const form = new FormData(event.currentTarget); const response = await apiFetch(`${apiUrl}/api/me`, { method: "PATCH", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ name: form.get("name"), phone: form.get("phone"), jobTitle: form.get("jobTitle"), avatarUrl: profile.avatarUrl ?? null }) }); const data = await response.json() as SessionUser | { message?: string }; setSaving(false); if (!response.ok || !("id" in data)) return setMessage("message" in data ? data.message || "Não foi possível salvar o perfil." : "Não foi possível salvar o perfil."); setProfile(data); onSessionUpdate({ token: session.token, user: data }); setMessage("Perfil atualizado."); };
  return <section className="page profile-page"><div className="page-heading"><div><p className="eyebrow">CONTA PESSOAL</p><h1>Meu perfil</h1><p className="muted">Mantenha seus dados e sua identificação no sistema atualizados.</p></div></div><section className="panel profile-panel"><form autoComplete="off" key={`${profile.id}-${profile.name}-${profile.phone ?? ""}-${profile.jobTitle ?? ""}`} onSubmit={save}><div className="profile-identity"><div className="profile-avatar-wrap"><UserAvatar user={profile} large /><label className="avatar-upload"><Camera size={16} /><span>Alterar foto</span><input autoComplete="off" type="file" accept="image/png,image/jpeg,image/webp" onChange={selectImage} /></label></div><div><h2>{profile.name}</h2><p>{profile.email}</p><span className={`status status--${profile.role === "admin" ? "info" : "neutral"}`}>{profile.role === "admin" ? "Administrador" : "Operador"}</span></div></div><div className="profile-fields"><label className="field"><span>Nome completo</span><input autoComplete="off" name="name" required defaultValue={profile.name} key={`name-${profile.name}`} /></label><label className="field"><span>E-mail</span><input autoComplete="off" value={profile.email} disabled /></label><label className="field"><span>Cargo ou área</span><input autoComplete="off" name="jobTitle" defaultValue={profile.jobTitle} placeholder="Ex.: Analista de importação" /></label><label className="field"><span>Telefone</span><input autoComplete="off" name="phone" defaultValue={profile.phone} inputMode="tel" placeholder="(11) 99999-9999" /></label></div>{message && <p className="users-message" role="status">{message}</p>}<div className="profile-actions"><button className="button button--primary" disabled={saving}>{saving ? "Salvando…" : "Salvar perfil"}</button></div></form></section>{avatarFile && <AvatarEditorDialog file={avatarFile} saving={saving} onClose={() => setAvatarFile(null)} onSave={uploadAvatar} />}</section>;
}

function TimelineEntryForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form autoComplete="off" className="form-grid" onSubmit={onSubmit}><label className="field full"><span>Marco</span><input autoComplete="off" name="title" required placeholder="Ex.: Conhecimento de embarque recebido" autoFocus /></label><label className="field"><span>Data e hora</span><DatePicker name="occurredAt" label="Data e hora" withTime required defaultValue={localDateTimeValue(new Date())} /></label><label className="field"><span>Tipo</span><FieldSelect label="Tipo de marco" name="type" defaultValue="milestone"><SelectOption value="milestone">Marco operacional</SelectOption><SelectOption value="status">Atualização de status</SelectOption><SelectOption value="note">Observação</SelectOption></FieldSelect></label><label className="field full"><span>Detalhes</span><input autoComplete="off" name="description" placeholder="Contexto para a equipe" /></label><button className="button button--primary form-submit"><Plus size={18} /> Registrar marco</button></form>; }
function OperationTaskForm({ onSubmit, users, usersLoading, task }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void; users: SessionUser[]; usersLoading: boolean; task: OperationTask | null }) {
  const locale = useLocale();
  const existingUser = task?.assigneeId ? users.find((user) => user.id === task.assigneeId) : users.find((user) => user.name === task?.assignee);
  const [assigneeId, setAssigneeId] = useState(existingUser?.id || (task?.assignee ? "legacy" : "unassigned"));
  const assignedUser = users.find((user) => user.id === assigneeId);
  const unassigned = <span className="assignee-option assignee-option--empty"><UserRound aria-hidden="true" /><span>{translateUiText(locale, "Sem responsável")}</span></span>;
  return <form autoComplete="off" className="form-grid" onSubmit={onSubmit} data-localized>
    <label className="field full"><span>{translateUiText(locale, "Pendência")}</span><Input name="title" required defaultValue={task?.title} placeholder={translateUiText(locale, "Ex.: Conferir invoice antes do registro")} autoFocus /></label>
    <div className="field"><span id="task-assignee-label">{translateUiText(locale, "Responsável")}</span>{usersLoading ? <Skeleton className="skeleton--input" /> : <Select name="assigneeId" value={assigneeId} onValueChange={setAssigneeId}>
      <SelectTrigger className="operation-assignee__select" aria-labelledby="task-assignee-label"><SelectValue>{assignedUser ? <span className="assignee-option"><UserAvatar user={assignedUser} /><span>{assignedUser.name}</span></span> : assigneeId === "legacy" ? task?.assignee : unassigned}</SelectValue></SelectTrigger>
      <SelectContent className="operation-assignee__content" sideOffset={6}><SelectItem value="unassigned" hideIndicator>{unassigned}</SelectItem>{task?.assignee && assigneeId === "legacy" && <SelectItem value="legacy" hideIndicator>{task.assignee}</SelectItem>}{users.map((user) => <SelectItem value={user.id} key={user.id} hideIndicator><span className="assignee-option"><UserAvatar user={user} /><span>{user.name}</span></span></SelectItem>)}</SelectContent>
    </Select>}</div>
    <label className="field"><span>{translateUiText(locale, "Prazo")}</span><DatePicker name="dueDate" label="Prazo" defaultValue={task?.dueDate} /></label>
    <Button type="submit" className="button button--primary form-submit" disabled={usersLoading}>{task ? <Pencil size={18} /> : <Plus size={18} />} {translateUiText(locale, task ? "Salvar alterações" : "Criar pendência")}</Button>
  </form>;
}
function OperationDocumentForm({ onSubmit }: { onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { return <form autoComplete="off" className="form-grid" onSubmit={onSubmit}><label className="field"><span>Tipo</span><FieldSelect label="Tipo de documento" name="type" defaultValue="Commercial Invoice"><SelectOption>Commercial Invoice</SelectOption><SelectOption>Packing List</SelectOption><SelectOption>Bill of Lading</SelectOption><SelectOption>Licença de Importação</SelectOption><SelectOption>Comprovante de pagamento</SelectOption><SelectOption>Outro</SelectOption></FieldSelect></label><label className="field"><span>Situação</span><FieldSelect label="Situação do documento" name="status" defaultValue="available"><SelectOption value="available">Disponível</SelectOption><SelectOption value="pending">Pendente</SelectOption><SelectOption value="expired">Vencido</SelectOption></FieldSelect></label><label className="field full"><span>Nome do documento</span><input autoComplete="off" name="title" required placeholder="Ex.: CI 2026-091" autoFocus /></label><label className="field"><span>Referência</span><input autoComplete="off" name="reference" placeholder="Número do documento" /></label><label className="field"><span>Data de emissão</span><DatePicker name="issuedAt" label="Data de emissão" /></label><label className="field"><span>Validade</span><DatePicker name="expiresAt" label="Validade" /></label><button className="button button--primary form-submit"><FileText size={18} /> Registrar documento</button></form>; }
function ItemForm({ item, onSubmit, token, budget }: { budget?: ImportBudget; item: ImportItem | null; onSubmit: (event: FormEvent<HTMLFormElement>) => void; token: string }) { return <form autoComplete="off" className="form-grid item-form" onSubmit={onSubmit}><label className="field full"><span>Produto</span><input autoComplete="off" name="name" required placeholder="Descrição comercial" defaultValue={item?.name} autoFocus /></label><label className="field"><span>Nome em chinês (original)</span><Input name="chineseName" lang="zh" defaultValue={item?.chineseName} readOnly={Boolean(item?.chineseName)} /></label><label className="field"><span>Nome em inglês</span><input autoComplete="off" name="englishName" placeholder="Product name" defaultValue={item?.englishName} /></label><label className="field"><span>SKU</span><input autoComplete="off" name="sku" placeholder="Código interno" defaultValue={item?.sku} /></label><label className="field full"><span>Descrição para comércio exterior</span><Textarea name="description" rows={3} className="item-description" placeholder="Material, modelo, finalidade e composição" defaultValue={item?.description} /></label><NcmField initialCode={item?.ncm} apiUrl={apiUrl} token={token} /><label className="field"><span>Quantidade</span><NumberInput name="quantity" required min="1" defaultValue={item?.quantity} decimalScale={0} /></label><label className="field"><span>Preço unitário (US$)</span><NumberInput name="unitPriceUsd" required min="0" defaultValue={item?.unitPriceUsd} decimalScale={10} fixedDecimalScale={false} currency="USD" /></label><label className="field"><span>Peso bruto unitário (kg)</span><NumberInput name="grossWeightKg" required min="0" defaultValue={item?.grossWeightKg} decimalScale={3} suffix="kg" /></label><label className="field"><span>Peso líquido total (kg)</span><NumberInput name="netWeightKg" min="0" defaultValue={item?.netWeightKg} decimalScale={6} suffix="kg" /></label><label className="field"><span>Caixas</span><NumberInput name="boxCount" min="0" defaultValue={item?.boxCount} decimalScale={0} /></label><label className="field"><span>Peso por caixa (kg)</span><NumberInput name="boxWeightKg" min="0" defaultValue={item?.boxWeightKg} decimalScale={3} suffix="kg" /></label><label className="field"><span>Unidades por caixa</span><NumberInput name="unitsPerBox" min="0" defaultValue={item?.unitsPerBox} decimalScale={0} /></label><label className="field"><span>Volume total (m³)</span><NumberInput name="totalVolumeM3" min="0" defaultValue={item?.totalVolumeM3} decimalScale={4} suffix="m³" /></label><ProductTaxFields item={item} budget={budget} /><button className="button button--primary form-submit" type="submit">{item ? <Pencil size={18} /> : <PackagePlus size={18} />}{item ? " Salvar alterações" : " Adicionar produto"}</button></form>; }
function CustomerForm({ customer, onSubmit, onLookup, onAddressLookup, onCancel }: { customer: Customer | null; onSubmit: (event: FormEvent<HTMLFormElement>) => void; onLookup: (taxId: string) => Promise<CompanyLookup>; onAddressLookup: (postalCode: string) => Promise<AddressLookup>; onCancel?: () => void }) {
  const formRef = useRef<HTMLFormElement>(null);
  const [activeTab, setActiveTab] = useState<"main" | "address" | "contact">("main");
  const [taxId, setTaxId] = useState(() => formatCnpj(customer?.taxId ?? ""));
  const [postalCode, setPostalCode] = useState(() => formatCep(customer?.postalCode ?? ""));
  const [lookupMessage, setLookupMessage] = useState("");
  const [addressMessage, setAddressMessage] = useState("");
  const [isLookingUp, setIsLookingUp] = useState(false);
  const [isLookingUpAddress, setIsLookingUpAddress] = useState(false);
  const fill = (name: keyof CompanyLookup | keyof AddressLookup, value?: string) => { const field = formRef.current?.elements.namedItem(name) as HTMLInputElement | null; if (field && value) field.value = value; };
  const lookup = async (value: string) => {
    const raw = cnpjRaw(value);
    if (raw.length < 14) return setLookupMessage("Informe os 14 caracteres do CNPJ para consultar a Receita Federal.");
    if (!isValidCnpj(raw)) return setLookupMessage("CNPJ inválido. Confira os dígitos verificadores.");
    setIsLookingUp(true); setLookupMessage("Consultando dados cadastrais…");
    try { const company = await onLookup(raw); (Object.entries(company) as Array<[keyof CompanyLookup, string | undefined]>).forEach(([name, fieldValue]) => fill(name, fieldValue)); setLookupMessage("Dados cadastrais preenchidos. Revise antes de salvar."); }
    catch (error) { setLookupMessage(error instanceof Error ? error.message : "Não foi possível consultar o CNPJ."); }
    finally { setIsLookingUp(false); }
  };
  const lookupAddress = async (value: string) => {
    const raw = cepRaw(value);
    if (raw.length < 8) return setAddressMessage("Informe os 8 dígitos do CEP para consultar o endereço.");
    setIsLookingUpAddress(true); setAddressMessage("Consultando endereço…");
    try { const address = await onAddressLookup(raw); (Object.entries(address) as Array<[keyof AddressLookup, string | undefined]>).forEach(([name, fieldValue]) => fill(name, fieldValue)); setPostalCode(formatCep(address.postalCode || raw)); setAddressMessage(""); }
    catch (error) { setAddressMessage(error instanceof Error ? error.message : "Não foi possível consultar o CEP."); }
    finally { setIsLookingUpAddress(false); }
  };
  const changeTaxId = (value: string) => { const formatted = formatCnpj(value); setTaxId(formatted); setLookupMessage(""); if (cnpjRaw(formatted).length === 14) void lookup(formatted); };
  const changePostalCode = (value: string) => { const formatted = formatCep(value); setPostalCode(formatted); setAddressMessage(""); if (cepRaw(formatted).length === 8) void lookupAddress(formatted); };
  const submit = (event: FormEvent<HTMLFormElement>) => { if (!isValidCnpj(taxId)) { event.preventDefault(); setActiveTab("main"); setLookupMessage("Informe um CNPJ válido antes de salvar."); return; } onSubmit(event); };
  const tab = (id: "main" | "address" | "contact", label: string, position: number) => <button className={`customer-form__tab ${activeTab === id ? "is-active" : ""}`} type="button" role="tab" aria-selected={activeTab === id} aria-controls={`customer-panel-${id}`} id={`customer-tab-${id}`} onClick={() => setActiveTab(id)}><b>{position}</b>{label}</button>;
  return <form autoComplete="off" ref={formRef} className="form-grid customer-form" onSubmit={submit}>{onCancel && <button className="text-button form-back" type="button" onClick={onCancel}><ArrowLeft size={16} /> Voltar à importação</button>}<div className="customer-form__tabs" role="tablist" aria-label="Etapas do cadastro do cliente">{tab("main", "Dados principais", 1)}{tab("address", "Endereço", 2)}{tab("contact", "Contato", 3)}</div><div className="customer-form__panel full" id="customer-panel-main" role="tabpanel" aria-labelledby="customer-tab-main" hidden={activeTab !== "main"}><p className="customer-form__hint">Comece pela identificação da empresa. A consulta oficial preenche os dados disponíveis.</p><div className="customer-form__fields"><label className="field full"><span>CNPJ</span><input name="taxId" required value={taxId} onChange={(event) => changeTaxId(event.target.value)} onBlur={() => void lookup(taxId)} inputMode="text" autoCapitalize="characters" autoComplete="off" maxLength={18} placeholder="12.345.678/0001-95 ou 12.ABC.345/01DE-35" aria-describedby="cnpj-help" />{isLookingUp && <Skeleton className="skeleton--helper" />}{lookupMessage && <small id="cnpj-help" className={lookupMessage.startsWith("CNPJ inválido") || lookupMessage.startsWith("Informe um CNPJ") || lookupMessage.startsWith("Não foi") ? "field-error" : "field-help"} aria-live="polite">{isLookingUp ? "Consultando dados cadastrais…" : lookupMessage}</small>}</label><label className="field full"><span>Razão social</span><input autoComplete="off" name="legalName" required defaultValue={customer?.legalName} placeholder="Empresa Importadora Ltda." /></label><label className="field"><span>Nome fantasia</span><input autoComplete="off" name="tradeName" defaultValue={customer?.tradeName} placeholder="Como será exibido no sistema" /></label><label className="field"><span>Situação cadastral</span><input autoComplete="off" name="registrationStatus" defaultValue={customer?.registrationStatus} placeholder="Preenchida pela consulta" /></label></div></div><div className="customer-form__panel full" id="customer-panel-address" role="tabpanel" aria-labelledby="customer-tab-address" hidden={activeTab !== "address"}><p className="customer-form__hint">Digite o CEP para preencher o endereço pelo ViaCEP. Todos os campos continuam editáveis.</p><div className="customer-form__fields"><label className="field"><span>CEP</span><input name="postalCode" value={postalCode} onChange={(event) => changePostalCode(event.target.value)} onBlur={() => void lookupAddress(postalCode)} inputMode="numeric" autoComplete="off" maxLength={9} placeholder="00000-000" aria-describedby="cep-help" />{isLookingUpAddress && <Skeleton className="skeleton--helper" />}{addressMessage && <small id="cep-help" className={addressMessage.startsWith("CEP não") || addressMessage.startsWith("Não foi") ? "field-error" : "field-help"} aria-live="polite">{isLookingUpAddress ? "Consultando endereço…" : addressMessage}</small>}</label><label className="field"><span>Número</span><input autoComplete="off" name="number" defaultValue={customer?.number} placeholder="Número" /></label><label className="field full"><span>Logradouro</span><input name="street" defaultValue={customer?.street} placeholder="Rua, avenida ou rodovia" autoComplete="off" /></label><label className="field"><span>Complemento</span><input name="complement" defaultValue={customer?.complement} placeholder="Sala, bloco ou referência" autoComplete="off" /></label><label className="field"><span>Bairro</span><input name="district" defaultValue={customer?.district} placeholder="Bairro" autoComplete="off" /></label><label className="field"><span>Cidade</span><input name="city" defaultValue={customer?.city} placeholder="Cidade" autoComplete="off" /></label><label className="field"><span>UF</span><input name="state" defaultValue={customer?.state} maxLength={2} autoCapitalize="characters" placeholder="SP" autoComplete="off" /></label></div></div><div className="customer-form__panel full" id="customer-panel-contact" role="tabpanel" aria-labelledby="customer-tab-contact" hidden={activeTab !== "contact"}><p className="customer-form__hint">Defina a pessoa e os canais que receberão atualizações da operação.</p><div className="customer-form__fields"><label className="field full"><span>Responsável</span><input name="contactName" defaultValue={customer?.contactName} placeholder="Nome do contato" autoComplete="off" /></label><label className="field"><span>E-mail</span><input name="email" type="email" defaultValue={customer?.email} placeholder="contato@empresa.com.br" autoComplete="off" /></label><label className="field"><span>Telefone</span><input name="phone" type="tel" defaultValue={customer?.phone} placeholder="+55 11 99999-9999" autoComplete="off" /></label></div></div><div className="customer-form__actions full"><button className="button button--secondary" type="button" onClick={() => setActiveTab(activeTab === "main" ? "contact" : activeTab === "address" ? "main" : "address")}>Anterior</button>{activeTab !== "contact" ? <button className="button button--primary" type="button" onClick={() => setActiveTab(activeTab === "main" ? "address" : "contact")}>Continuar</button> : <button className="button button--primary" type="submit"><Users size={18} /> {customer ? "Salvar alterações" : "Salvar cliente"}</button>}</div></form>;
}
function CustomersView({ customers, operations, onNew, onEdit }: { customers: Customer[]; operations: ImportOperation[]; onNew: () => void; onEdit: (customer: Customer) => void }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState<"operations" | "name" | "newest">("operations");
  const [status, setStatus] = useState<Customer["status"] | "all">("all");
  const operationCount = (customer: Customer) => operations.filter((operation) => operation.customerId === customer.id || operation.customer === customer.tradeName).length;
  const visibleCustomers = customers.filter((customer) => (status === "all" || customer.status === status) && `${customer.legalName} ${customer.tradeName} ${customer.taxId}`.toLowerCase().includes(query.toLowerCase())).sort((left, right) => {
    if (sort === "operations") return operationCount(right) - operationCount(left) || left.legalName.localeCompare(right.legalName, "pt-BR");
    if (sort === "newest") return new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime();
    return (left.tradeName || left.legalName).localeCompare(right.tradeName || right.legalName, "pt-BR");
  });
  return <section className="page"><div className="page-heading"><div><p className="eyebrow">CADASTRO E RELACIONAMENTO</p><h1>Clientes</h1><p className="muted">Empresas vinculadas às operações de importação.</p></div><button className="button button--primary" onClick={onNew}><Plus size={18} /> Novo cliente</button></div><section className="panel customers-panel"><div className="customers-toolbar"><label className="search-field"><Search size={17} /><input autoComplete="off" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por empresa ou CNPJ" aria-label="Buscar clientes" /></label><label className="customers-sort"><span>Status</span><FieldSelect label="Filtrar clientes por status" value={status} onValueChange={(value) => setStatus(value as Customer["status"] | "all")}><SelectOption value="all">Todos</SelectOption><SelectOption value="active">Ativos</SelectOption><SelectOption value="inactive">Inativos</SelectOption></FieldSelect></label><label className="customers-sort"><span>Ordenar</span><FieldSelect label="Ordenar clientes" value={sort} onValueChange={(value) => setSort(value as "operations" | "name" | "newest")}><SelectOption value="operations">Mais operações</SelectOption><SelectOption value="name">Nome da empresa</SelectOption><SelectOption value="newest">Cadastro mais recente</SelectOption></FieldSelect></label><span>{visibleCustomers.length} cliente{visibleCustomers.length === 1 ? "" : "s"}</span></div><div className="table-scroll"><table><thead><tr><th>Empresa</th><th>CNPJ</th><th>Responsável</th><th>Contato</th><th>Operações</th><th>Status</th><th><span className="sr-only">Ações</span></th></tr></thead><tbody>{visibleCustomers.length === 0 ? <tr><td className="empty-cell" colSpan={7}>Nenhum cliente encontrado.</td></tr> : visibleCustomers.map((customer) => <tr key={customer.id}><td><strong>{customer.tradeName || customer.legalName}</strong><small>{customer.legalName}</small></td><td>{customer.taxId}</td><td>{customer.contactName}</td><td><strong>{customer.email}</strong><small>{customer.phone}</small></td><td>{operationCount(customer)}</td><td><span className={`status status--${customer.status === "active" ? "success" : "neutral"}`}>{customer.status === "active" ? "Ativo" : "Inativo"}</span></td><td><button className="table-action" onClick={() => onEdit(customer)} aria-label={`Editar ${customer.tradeName || customer.legalName}`}><Pencil size={16} /></button></td></tr>)}</tbody></table></div></section></section>;
}
